INSERT INTO `rhesis` VALUES (1,'山有木兮木有枝，心悦君兮君不知。','佚名《越人歌》'),(2,'人生若只如初见，何事秋风悲画扇。','纳兰性德《木兰词·拟古决绝词柬友》'),(3,'十年生死两茫茫，不思量，自难忘。','苏轼《江城子·乙卯正月二十日夜记梦》'),(4,'曾经沧海难为水，除却巫山不是云。','元稹《离思五首·其四》'),(5,'玲珑骰子安红豆，入骨相思知不知。','温庭筠《南歌子词二首 / 新添声杨柳枝词》'),(6,'人生如逆旅，我亦是行人。','苏轼《临江仙·送钱穆父》'),(7,'只愿君心似我心，定不负相思意。','李之仪《卜算子·我住长江头》'),(8,'平生不会相思，才会相思，便害相思。','徐再思《折桂令·春情》'),(9,'愿得一心人，白头不相离。','卓文君《白头吟》'),(10,'山无陵，江水为竭。冬雷震震，夏雨雪。天地合，乃敢与君绝。','佚名《上邪》'),(11,'两情若是久长时，又岂在朝朝暮暮。','秦观《鹊桥仙·纤云弄巧》'),(12,'入我相思门，知我相思苦。','李白《三五七言 / 秋风词》'),(13,'去年今日此门中，人面桃花相映红。','崔护《题都城南庄》'),(14,'人生自是有情痴，此恨不关风与月。','欧阳修《玉楼春·尊前拟把归期说》'),(15,'雨打梨花深闭门，忘了青春，误了青春。','唐寅《一剪梅·雨打梨花深闭门》'),(16,'花自飘零水自流。一种相思，两处闲愁。','李清照《一剪梅·红藕香残玉簟秋》'),(17,'一日不见兮，思之如狂。','司马相如《凤求凰 / 琴歌》'),(18,'问世间，情为何物，直教生死相许？','元好问《摸鱼儿·雁丘词 / 迈陂塘》'),(19,'身无彩凤双飞翼，心有灵犀一点通。','李商隐《无题·昨夜星辰昨夜风》'),(20,'世间无限丹青手，一片伤心画不成。','高蟾《金陵晚望》'),(21,'少年不识愁滋味，爱上层楼。爱上层楼。为赋新词强说愁。','辛弃疾《丑奴儿·书博山道中壁》'),(22,'执子之手，与子偕老。','佚名《击鼓》'),(23,'滚滚长江东逝水，浪花淘尽英雄。','杨慎《临江仙·滚滚长江东逝水》'),(24,'一往情深深几许？深山夕照深秋雨。','纳兰性德《蝶恋花·出塞》'),(25,'林花谢了春红，太匆匆。无奈朝来寒雨，晚来风。','李煜《相见欢·林花谢了春红》'),(26,'一生大笑能几回，斗酒相逢须醉倒。','岑参《凉州馆中与诸判官夜集》'),(27,'此情可待成追忆？只是当时已惘然。','李商隐《锦瑟》'),(28,'自在飞花轻似梦，无边丝雨细如愁。','秦观《浣溪沙·漠漠轻寒上小楼》'),(29,'思悠悠，恨悠悠，恨到归时方始休。','白居易《长相思·汴水流》'),(30,'春风得意马蹄疾，一日看尽长安花。','孟郊《登科后》'),(31,'一声梧叶一声秋，一点芭蕉一点愁，三更归梦三更后。','徐再思《水仙子·夜雨》'),(32,'春宵一刻值千金，花有清香月有阴。','苏轼《春宵·春宵一刻值千金》'),(33,'菩提本无树，明镜亦非台。','惠能《菩提偈》'),(34,'人面不知何处去，桃花依旧笑春风。','崔护《题都城南庄》'),(35,'时光只解催人老，不信多情，长恨离亭，泪滴春衫酒易醒。','晏殊《采桑子·时光只解催人老》'),(36,'浮云一别后，流水十年间。','韦应物《淮上喜会梁川故人 / 淮上喜会梁州故人》'),(37,'疏影横斜水清浅，暗香浮动月黄昏。','林逋《山园小梅·其一》'),(38,'昨夜西风凋碧树。独上高楼，望尽天涯路。','晏殊《蝶恋花·槛菊愁烟兰泣露》'),(39,'若是前生未有缘，待重结、来生愿。','乐婉《卜算子·答施》'),(40,'抽刀断水水更流，举杯消愁愁更愁。','李白《宣州谢脁楼饯别校书叔云 / 陪侍御叔华登楼歌》'),(41,'取次花丛懒回顾，半缘修道半缘君。','元稹《离思五首·其四》'),(42,'怕相思，已相思，轮到相思没处辞，眉间露一丝。','俞彦《长相思·折花枝》'),(43,'溪云初起日沉阁，山雨欲来风满楼。','许浑《咸阳城东楼 / 咸阳城西楼晚眺 / 西门》'),(44,'似此星辰非昨夜，为谁风露立中宵。','黄景仁《绮怀》'),(45,'近水楼台先得月，向阳花木易为春。','苏麟《断句》'),(46,'还君明珠双泪垂，恨不相逢未嫁时。','张籍《节妇吟·寄东平李司空师道》'),(47,'问君能有几多愁？恰似一江春水向东流。','李煜《虞美人·春花秋月何时了》'),(48,'一骑红尘妃子笑，无人知是荔枝来。','杜牧《过华清宫绝句三首》'),(49,'枯藤老树昏鸦，小桥流水人家，古道西风瘦马。','马致远《天净沙·秋思》'),(50,'天涯地角有穷时，只有相思无尽处。','晏殊《玉楼春·春恨》'),(51,'夜月一帘幽梦，春风十里柔情。','秦观《八六子·倚危亭》'),(52,'落花人独立，微雨燕双飞。','晏几道《临江仙·梦后楼台高锁》'),(53,'君埋泉下泥销骨，我寄人间雪满头。','白居易《梦微之》'),(54,'行到水穷处，坐看云起时。','王维《终南别业 / 初至山中 / 入山寄城中故人》'),(55,'仰天大笑出门去，我辈岂是蓬蒿人。','李白《南陵别儿童入京》'),(56,'空山新雨后，天气晚来秋。','王维《山居秋暝》'),(57,'沾衣欲湿杏花雨，吹面不寒杨柳风。','志南《绝句》'),(58,'今人不见古时月，今月曾经照古人。','李白《把酒问月·故人贾淳令予问之》'),(59,'云想衣裳花想容，春风拂槛露华浓。','李白《清平调·其一》'),(60,'休对故人思故国，且将新火试新茶。诗酒趁年华。','苏轼《望江南·超然台作》'),(61,'凤凰台上凤凰游，凤去台空江自流。','李白《登金陵凤凰台》'),(62,'黄沙百战穿金甲，不破楼兰终不还。','王昌龄《从军行七首·其四》'),(63,'红酥手，黄縢酒，满城春色宫墙柳。','陆游《钗头凤·红酥手》'),(64,'直道相思了无益，未妨惆怅是清狂。','李商隐《无题·重帏深下莫愁堂》'),(65,'独立寒秋，湘江北去，橘子洲头。','毛泽东《沁园春·长沙》'),(66,'宁可枝头抱香死，何曾吹落北风中。','郑思肖《画菊》'),(67,'劝君莫惜金缕衣，劝君惜取少年时。','杜秋娘《金缕衣》'),(68,'同是天涯沦落人，相逢何必曾相识！','白居易《琵琶行 / 琵琶引》'),(69,'被酒莫惊春睡重，赌书消得泼茶香，当时只道是寻常。','纳兰性德《浣溪沙·谁念西风独自凉》'),(70,'人言落日是天涯，望极天涯不见家。','李觏《乡思》'),(71,'醉后不知天在水，满船清梦压星河。','唐温如《题龙阳县青草湖》'),(72,'青山依旧在，几度夕阳红。','杨慎《临江仙·滚滚长江东逝水》'),(73,'桃李春风一杯酒，江湖夜雨十年灯。','黄庭坚《寄黄几复》'),(74,'桃之夭夭，灼灼其华。','佚名《桃夭》'),(75,'小楼一夜听春雨，深巷明朝卖杏花。','陆游《临安春雨初霁》'),(76,'采得百花成蜜后，为谁辛苦为谁甜。','罗隐《蜂》'),(77,'春蚕到死丝方尽，蜡炬成灰泪始干。','李商隐《无题·相见时难别亦难》'),(78,'换我心，为你心，始知相忆深。','顾夐《诉衷情·永夜抛人何处去》'),(79,'男儿何不带吴钩，收取关山五十州。','李贺《南园十三首·其五》'),(80,'寂寞空庭春欲晚，梨花满地不开门。','刘方平《春怨》'),(81,'多情自古伤离别，更那堪冷落清秋节！','柳永《雨霖铃·寒蝉凄切》'),(82,'夜来幽梦忽还乡。小轩窗。正梳妆。相顾无言，惟有泪千行。','苏轼《江城子·乙卯正月二十日夜记梦》'),(83,'海上生明月，天涯共此时。','张九龄《望月怀远》'),(84,'莫愁前路无知己，天下谁人不识君。','高适《别董大二首》'),(85,'月上柳梢头，人约黄昏后。','欧阳修《生查子·元夕》'),(86,'闻君有两意，故来相决绝。','卓文君《白头吟》'),(87,'人间四月芳菲尽，山寺桃花始盛开。','白居易《大林寺桃花》'),(88,'生当复来归，死当长相思。','佚名《留别妻》'),(89,'江碧鸟逾白，山青花欲燃。','杜甫《绝句二首》'),(90,'醉卧沙场君莫笑，古来征战几人回？','王翰《凉州词二首·其一》'),(91,'当年不肯嫁春风，无端却被秋风误。','贺铸《芳心苦·杨柳回塘》'),(92,'落霞与孤鹜齐飞，秋水共长天一色。','王勃《滕王阁序》'),(93,'心似双丝网，中有千千结。','张先《千秋岁·数声鶗鴂》'),(94,'美人自刎乌江岸，战火曾烧赤壁山，将军空老玉门关。','张可久《卖花声·怀古》'),(95,'东风夜放花千树。更吹落、星如雨。','辛弃疾《青玉案·元夕》'),(96,'不经一番寒彻骨，怎得梅花扑鼻香。','黄蘖禅师《上堂开示颂》'),(97,'风萧萧兮易水寒，壮士一去兮不复还。','佚名《荆轲歌 / 渡易水歌》'),(98,'日日思君不见君，共饮长江水。','李之仪《卜算子·我住长江头》'),(99,'月有盈亏花有开谢，想人生最苦离别。','张鸣善《普天乐·咏世》'),(100,'二十四桥明月夜，玉人何处教吹箫？','杜牧《寄扬州韩绰判官》'),(101,'落红不是无情物，化作春泥更护花。','龚自珍《己亥杂诗·其五》'),(102,'世事漫随流水，算来一梦浮生。','李煜《乌夜啼·昨夜风兼雨》'),(103,'锦瑟无端五十弦，一弦一柱思华年。','李商隐《锦瑟》'),(104,'人到情多情转薄，而今真个悔多情。','纳兰性德《山花子·风絮飘残已化萍》'),(105,'渺万里层云，千山暮雪，只影向谁去？','元好问《摸鱼儿·雁丘词 / 迈陂塘》'),(106,'独自莫凭栏，无限江山，别时容易见时难。','李煜《浪淘沙令·帘外雨潺潺》'),(107,'衰兰送客咸阳道。天若有情天亦老。','贺铸《行路难·缚虎手》'),(108,'美人卷珠帘，深坐颦蛾眉。','李白《怨情》'),(109,'万事到头都是梦，休休。明日黄花蝶也愁。','苏轼《南乡子·重九涵辉楼呈徐君猷》'),(110,'时人不识凌云木，直待凌云始道高。','杜荀鹤《小松》'),(111,'泪眼问花花不语，乱红飞过秋千去。','欧阳修《蝶恋花·庭院深深深几许》'),(112,'海水梦悠悠，君愁我亦愁。','佚名《西洲曲》'),(113,'酒逢知己千杯少，话不投机半句多。','欧阳修《春日西湖寄谢法曹韵》'),(114,'十年磨一剑，霜刃未曾试。','贾岛《剑客 / 述剑》'),(115,'盈盈一水间，脉脉不得语。','佚名《迢迢牵牛星》'),(116,'相思相见知何日？此时此夜难为情！','李白《三五七言 / 秋风词》'),(117,'大江东去，浪淘尽，千古风流人物。','苏轼《念奴娇·赤壁怀古》'),(118,'苟利国家生死以，岂因祸福避趋之！','林则徐《赴戍登程口占示家人·其二》'),(119,'呜呼！楚虽三户能亡秦，岂有堂堂中国空无人！','陆游《金错刀行》'),(120,'世人结交须黄金，黄金不多交不深。','张谓《题长安壁主人》'),(121,'竹外桃花三两枝，春江水暖鸭先知。','苏轼《惠崇春江晚景 / 惠崇春江晓景》'),(122,'白日放歌须纵酒，青春作伴好还乡。','杜甫《闻官军收河南河北》'),(123,'无可奈何花落去，似曾相识燕归来。','晏殊《浣溪沙·一曲新词酒一杯》'),(124,'射人先射马，擒贼先擒王。','杜甫《前出塞九首·其六》'),(125,'夕阳无限好，只是近黄昏。','李商隐《乐游原 / 登乐游原》'),(126,'梅须逊雪三分白，雪却输梅一段香。','卢梅坡《雪梅·其一》'),(127,'待到秋来九月八，我花开后百花杀。','黄巢《不第后赋菊》'),(128,'遇酒且呵呵，人生能几何！','韦庄《菩萨蛮·劝君今夜须沈醉》'),(129,'纸上得来终觉浅，绝知此事要躬行。','陆游《冬夜读书示子聿》'),(130,'长风破浪会有时，直挂云帆济沧海。','李白《行路难·其一》'),(131,'天长地久有时尽，此恨绵绵无绝期。','白居易《长恨歌》'),(132,'露从今夜白，月是故乡明。','杜甫《月夜忆舍弟》'),(133,'把酒祝东风。且共从容。','欧阳修《浪淘沙·把酒祝东风》'),(134,'物是人非事事休，欲语泪先流。','李清照《武陵春·春晚》'),(135,'酒入愁肠，化作相思泪。','范仲淹《苏幕遮·怀旧》'),(136,'欲把相思说似谁，浅情人不知。','晏几道《长相思·长相思》'),(137,'系我一生心，负你千行泪。','柳永《忆帝京·薄衾小枕凉天气》'),(138,'沉舟侧畔千帆过，病树前头万木春。','刘禹锡《酬乐天扬州初逢席上见赠》'),(139,'相思只在：丁香枝上，豆蔻梢头。','王雱《眼儿媚·杨柳丝丝弄轻柔》'),(140,'山重水复疑无路，柳暗花明又一村。','陆游《游山西村》'),(141,'晓看天色暮看云，行也思君，坐也思君。','唐寅《一剪梅·雨打梨花深闭门》'),(142,'相见时难别亦难，东风无力百花残。','李商隐《无题·相见时难别亦难》'),(143,'春心莫共花争发，一寸相思一寸灰！','李商隐《无题·飒飒东风细雨来》'),(144,'曾与美人桥上别，恨无消息到今朝。','刘禹锡《杨柳枝 / 柳枝词》'),(145,'肠已断，泪难收。相思重上小红楼。','辛弃疾《鹧鸪天·晚日寒鸦一片愁》'),(146,'山外青山楼外楼，西湖歌舞几时休？','林升《题临安邸》'),(147,'伤心桥下春波绿，曾是惊鸿照影来。','陆游《沈园二首》'),(148,'花无人戴，酒无人劝，醉也无人管。','黄公绍《青玉案·年年社日停针线》'),(149,'流水落花春去也，天上人间。','李煜《浪淘沙令·帘外雨潺潺》'),(150,'山一程，水一程，身向榆关那畔行，夜深千帐灯。','纳兰性德《长相思·山一程》'),(151,'无边落木萧萧下，不尽长江滚滚来。','杜甫《登高》'),(152,'寻寻觅觅，冷冷清清，凄凄惨惨戚戚。','李清照《声声慢·寻寻觅觅》'),(153,'兰有秀兮菊有芳，怀佳人兮不能忘。','刘彻《秋风辞》'),(154,'少年易老学难成，一寸光阴不可轻。','朱熹《劝学诗 / 偶成》'),(155,'读书不觉已春深，一寸光阴一寸金。','王贞白《白鹿洞二首·其一》'),(156,'韶华不为少年留。恨悠悠。几时休。','秦观《江城子·西城杨柳弄春柔》'),(157,'相思了无益，悔当初相见。','朱彝尊《忆少年·飞花时节》'),(158,'力拔山兮气盖世。时不利兮骓不逝。','项羽《垓下歌》'),(159,'渐行渐远渐无书，水阔鱼沉何处问。','欧阳修《玉楼春·别后不知君远近》'),(160,'落叶他乡树，寒灯独夜人。','马戴《灞上秋居》'),(161,'旧时王谢堂前燕，飞入寻常百姓家。','刘禹锡《乌衣巷》'),(162,'明月几时有？把酒问青天。','苏轼《水调歌头·丙辰中秋》'),(163,'思君如满月，夜夜减清辉。','张九龄《赋得自君之出矣》'),(164,'悠悠天宇旷，切切故乡情。','张九龄《西江夜行》'),(165,'洛阳亲友如相问，一片冰心在玉壶。','王昌龄《芙蓉楼送辛渐》'),(166,'无情不似多情苦。一寸还成千万缕。','晏殊《玉楼春·春恨》'),(167,'窈窕淑女，君子好逑。','佚名《关雎》'),(168,'结发为夫妻，恩爱两不疑。','佚名《留别妻》'),(169,'慈母手中线，游子身上衣。','孟郊《游子吟 / 迎母漂上作》'),(170,'会当凌绝顶，一览众山小。','杜甫《望岳》'),(171,'试问岭南应不好。却道。此心安处是吾乡。','苏轼《少年游·南海归赠王定国侍人寓娘》'),(172,'采菊东篱下，悠然见南山。','陶渊明《饮酒·其五》'),(173,'天街小雨润如酥，草色遥看近却无。','韩愈《早春呈水部张十八员外 / 初春小雨 / 早春》'),(174,'他年我若为青帝，报与桃花一处开。','黄巢《题菊花》'),(175,'以色事他人，能得几时好。','李白《妾薄命》'),(176,'人闲桂花落，夜静春山空。','王维《鸟鸣涧》'),(177,'但愿人长久，千里共婵娟。','苏轼《水调歌头·丙辰中秋》'),(178,'海内存知己，天涯若比邻。','王勃《送杜少府之任蜀州 / 送杜少府之任蜀川》'),(179,'枝上柳绵吹又少。天涯何处无芳草。','苏轼《蝶恋花·春景》'),(180,'夜阑卧听风吹雨，铁马冰河入梦来。','陆游《十一月四日风雨大作》'),(181,'花间一壶酒，独酌无相亲。','李白《月下独酌四首·其一》'),(182,'远看山有色，近听水无声。','王维《画》'),(183,'黑发不知勤学早，白首方悔读书迟。','颜真卿《劝学诗》'),(184,'世事短如春梦，人情薄似秋云。','朱敦儒《西江月·世事短如春梦》'),(185,'危楼高百尺，手可摘星辰。','李白《夜宿山寺》'),(186,'劝君更尽一杯酒，西出阳关无故人。','王维《渭城曲 / 送元二使安西》'),(187,'咬定青山不放松，立根原在破岩中。','郑燮《竹石》'),(188,'等闲识得东风面，万紫千红总是春。','朱熹《春日》'),(189,'沧海月明珠有泪，蓝田日暖玉生烟。','李商隐《锦瑟》'),(190,'多情只有春庭月，犹为离人照落花。','张泌《寄人》'),(191,'造物无言却有情，每于寒尽觉春生。','张维屏《新雷》'),(192,'晚来天欲雪，能饮一杯无。','白居易《问刘十九》'),(193,'江南可采莲，莲叶何田田。','佚名《江南》'),(194,'小荷才露尖尖角，早有蜻蜓立上头。','杨万里《小池》'),(195,'人生亦有命，安能行叹复坐愁？','鲍照《拟行路难·其四》'),(196,'云中谁寄锦书来，雁字回时，月满西楼。','李清照《一剪梅·红藕香残玉簟秋》'),(197,'春江潮水连海平，海上明月共潮生。','张若虚《春江花月夜》'),(198,'秦时明月汉时关，万里长征人未还。','王昌龄《出塞二首·其一》'),(199,'昔去雪如花，今来花似雪。','范云《别诗》'),(200,'朔风如解意，容易莫摧残。','崔道融《梅花》'),(201,'大漠孤烟直，长河落日圆。','王维《使至塞上》'),(202,'借问江潮与海水，何似君情与妾心？','白居易《浪淘沙·借问江潮与海水》'),(203,'春风又绿江南岸，明月何时照我还？','王安石《泊船瓜洲》'),(204,'兰陵美酒郁金香，玉碗盛来琥珀光。','李白《客中行 / 客中作》'),(205,'七八个星天外，两三点雨山前。','辛弃疾《西江月·夜行黄沙道中》'),(206,'水晶帘动微风起，满架蔷薇一院香。','高骈《山亭夏日》'),(207,'春风十里扬州路，卷上珠帘总不如。','杜牧《赠别》'),(208,'莫唱当年长恨歌，人间亦自有银河。','袁枚《马嵬》'),(209,'宣父犹能畏后生，丈夫未可轻年少。','李白《上李邕》'),(210,'伯牙鼓琴，志在高山','佚名《伯牙绝弦》'),(211,'故人西辞黄鹤楼，烟花三月下扬州。','李白《黄鹤楼送孟浩然之广陵》'),(212,'人生自古谁无死？留取丹心照汗青。','文天祥《过零丁洋》'),(213,'欲买桂花同载酒，终不是、少年游。','刘过《唐多令·芦叶满汀洲》'),(214,'青枫江上秋帆远，白帝城边古木疏。','高适《送李少府贬峡中王少府贬长沙》'),(215,'毕竟西湖六月中，风光不与四时同。','杨万里《晓出净慈寺送林子方》'),(216,'一寸柔肠情几许？薄衾孤枕，梦回人静，彻晓潇潇雨。','惠洪《青玉案·丝槐烟柳长亭路》'),(217,'自是人生长恨，水长东。','李煜《相见欢·林花谢了春红》'),(218,'出师未捷身先死，长使英雄泪满襟。','杜甫《蜀相》'),(219,'劝君莫惜花前醉，今年花谢，明年花谢，白了人头。','赵秉文《青杏儿·风雨替花愁》'),(220,'七夕今宵看碧霄，牵牛织女渡河桥。','林杰《乞巧》'),(221,'商女不知亡国恨，隔江犹唱后庭花。','杜牧《泊秦淮》'),(222,'两个黄鹂鸣翠柳，一行白鹭上青天。','杜甫《绝句》'),(223,'君知妾有夫，赠妾双明珠。','张籍《节妇吟·寄东平李司空师道》'),(224,'昨夜星辰昨夜风，画楼西畔桂堂东。','李商隐《无题·昨夜星辰昨夜风》'),(225,'绿蚁新醅酒，红泥小火炉。','白居易《问刘十九》'),(226,'东边日出西边雨，道是无晴却有晴。','刘禹锡《竹枝词二首·其一》'),(227,'谁家玉笛暗飞声，散入春风满洛城。','李白《春夜洛城闻笛 / 春夜洛阳城闻笛》'),(228,'墙角数枝梅，凌寒独自开。','王安石《梅花 / 梅》'),(229,'蝉噪林逾静，鸟鸣山更幽。','王籍《入若耶溪》'),(230,'日色欲尽花含烟，月明欲素愁不眠。','李白《长相思·其二》'),(231,'愿为西南风，长逝入君怀。','曹植《明月上高楼》'),(232,'近乡情更怯，不敢问来人。','宋之问《渡汉江》'),(233,'愿得此身长报国，何须生入玉门关。','戴叔伦《塞上曲二首·其二》'),(234,'谁念西风独自凉，萧萧黄叶闭疏窗，沉思往事立残阳。','纳兰性德《浣溪沙·谁念西风独自凉》'),(235,'君问归期未有期，巴山夜雨涨秋池。','李商隐《夜雨寄北》'),(236,'江畔何人初见月？江月何年初照人？','张若虚《春江花月夜》'),(237,'十年一觉扬州梦，赢得青楼薄幸名。','杜牧《遣怀》'),(238,'天生我材必有用，千金散尽还复来。','李白《将进酒》'),(239,'我住长江头，君住长江尾。','李之仪《卜算子·我住长江头》'),(240,'萧萧梧叶送寒声，江上秋风动客情。','叶绍翁《夜书所见》'),(241,'相逢一醉是前缘，风雨散、飘然何处。','苏轼《鹊桥仙·七夕》'),(242,'执手相看泪眼，竟无语凝噎。','柳永《雨霖铃·寒蝉凄切》'),(243,'世情薄，人情恶，雨送黄昏花易落。','唐婉《钗头凤·世情薄》'),(244,'南朝四百八十寺，多少楼台烟雨中。','杜牧《江南春》'),(245,'盛年不重来，一日难再晨。','陶渊明《杂诗·人生无根蒂》'),(246,'明月松间照，清泉石上流。','王维《山居秋暝》'),(247,'葡萄美酒夜光杯，欲饮琵琶马上催。','王翰《凉州词二首·其一》'),(248,'忽见陌头杨柳色，悔教夫婿觅封侯。','王昌龄《闺怨》'),(249,'相恨不如潮有信，相思始觉海非深。','白居易《浪淘沙·借问江潮与海水》'),(250,'山不在高，有仙则名。水不在深，有龙则灵。','刘禹锡《陋室铭》'),(251,'接天莲叶无穷碧，映日荷花别样红。','杨万里《晓出净慈寺送林子方》'),(252,'墙外行人，墙里佳人笑。','苏轼《蝶恋花·春景》'),(253,'松花酿酒，春水煎茶。','张可久《人月圆·山中书事》'),(254,'江南几度梅花发，人在天涯鬓已斑。','刘著《鹧鸪天·雪照山城玉指寒》'),(255,'大漠沙如雪，燕山月似钩。','李贺《马诗二十三首·其五》'),(256,'满目山河空念远，落花风雨更伤春。','晏殊《浣溪沙·一向年光有限身》'),(257,'若教眼底无离恨，不信人间有白头。','辛弃疾《鹧鸪天·晚日寒鸦一片愁》'),(258,'红泪偷垂，满眼春风百事非。','纳兰性德《采桑子·当时错》'),(259,'此情无计可消除，才下眉头，却上心头。','李清照《一剪梅·红藕香残玉簟秋》'),(260,'好雨知时节，当春乃发生。','杜甫《春夜喜雨》'),(261,'水光潋滟晴方好，山色空蒙雨亦奇。','苏轼《饮湖上初晴后雨二首·其二》'),(262,'日出江花红胜火，春来江水绿如蓝。','白居易《忆江南·江南好》'),(263,'易求无价宝，难得有情郎。','鱼玄机《赠邻女 / 寄李亿员外》'),(264,'去年花里逢君别，今日花开已一年。','韦应物《寄李儋元锡》'),(265,'风一更，雪一更，聒碎乡心梦不成，故园无此声。','纳兰性德《长相思·山一程》'),(266,'身既死兮神以灵，魂魄毅兮为鬼雄。','屈原《国殇》'),(267,'八阵图名成卧龙，六韬书功在飞熊。','查德卿《蟾宫曲·怀古》'),(268,'羌笛何须怨杨柳，春风不度玉门关。','王之涣《凉州词二首·其一》'),(269,'数人世相逢，百年欢笑，能得几回又。','何梦桂《摸鱼儿·记年时人人何处》'),(270,'青山绿水，白草红叶黄花。','白朴《天净沙·秋》'),(271,'新竹高于旧竹枝，全凭老干为扶持。','郑燮《新竹》'),(272,'秋阴不散霜飞晚，留得枯荷听雨声。','李商隐《宿骆氏亭寄怀崔雍崔衮》'),(273,'南风知我意，吹梦到西洲。','佚名《西洲曲》'),(274,'绿杨烟外晓寒轻，红杏枝头春意闹。','宋祁《玉楼春·春景》'),(275,'若待上林花似锦，出门俱是看花人。','杨巨源《城东早春》'),(276,'平生不下泪，于此泣无穷。','李白《江夏别宋之悌》'),(277,'金风玉露一相逢，便胜却人间无数。','秦观《鹊桥仙·纤云弄巧》'),(278,'我居北海君南海，寄雁传书谢不能。','黄庭坚《寄黄几复》'),(279,'柳庭风静人眠昼，昼眠人静风庭柳。','苏轼《菩萨蛮·回文夏闺怨》'),(280,'离离原上草，一岁一枯荣。','白居易《草 / 赋得古原草送别》'),(281,'嫦娥应悔偷灵药，碧海青天夜夜心。','李商隐《嫦娥》'),(282,'月落乌啼霜满天，江枫渔火对愁眠。','张继《枫桥夜泊 / 夜泊枫江》'),(283,'一道残阳铺水中，半江瑟瑟半江红。','白居易《暮江吟》'),(284,'博观而约取，厚积而薄发','苏轼《稼说送张琥》'),(285,'春水碧于天，画船听雨眠。','韦庄《菩萨蛮·人人尽说江南好》'),(286,'孤灯不明思欲绝，卷帷望月空长叹。','李白《长相思·其一》'),(287,'山远天高烟水寒，相思枫叶丹。','李煜《长相思·一重山》'),(288,'江南无所有，聊赠一枝春。','陆凯《赠范晔诗》'),(289,'老来情味减，对别酒、怯流年。','辛弃疾《木兰花慢·滁州送范倅》'),(290,'宁不知倾城与倾国。佳人难再得。','李延年《李延年歌》'),(291,'月儿弯弯照九州，几家欢乐几家愁。','佚名《月儿弯弯照九州》'),(292,'不茶不饭，不言不语，一味供他憔悴。','蜀妓《鹊桥仙·说盟说誓》'),(293,'相思一夜梅花发，忽到窗前疑是君。','卢仝《有所思》'),(294,'情人怨遥夜，竟夕起相思。','张九龄《望月怀远》'),(295,'不识庐山真面目，只缘身在此山中。','苏轼《题西林壁》'),(296,'多情却被无情恼，今夜还如昨夜长。','元好问《鹧鸪天·候馆灯昏雨送凉》'),(297,'似花还似非花，也无人惜从教坠。','苏轼《水龙吟·次韵章质夫杨花词》'),(298,'舞低杨柳楼心月，歌尽桃花扇底风。','晏几道《鹧鸪天·彩袖殷勤捧玉钟》'),(299,'莫笑贱贫夸富贵，共成枯骨两何如？','白居易《放言五首·其四》'),(300,'若言琴上有琴声，放在匣中何不鸣？','苏轼《琴诗》'),(301,'春潮带雨晚来急，野渡无人舟自横。','韦应物《滁州西涧》'),(302,'风淅淅，雨纤纤。难怪春愁细细添。','纳兰性德《赤枣子·风淅淅》'),(303,'位卑未敢忘忧国，事定犹须待阖棺。','陆游《病起书怀》'),(304,'悲莫悲生离别，乐莫乐新相识，儿女古今情。','辛弃疾《水调歌头·壬子三山被召陈端仁给事饮饯席上作》'),(305,'水是眼波横，山是眉峰聚。','王观《卜算子·送鲍浩然之浙东》'),(306,'试玉要烧三日满，辨材须待七年期。','白居易《放言五首·其三》'),(307,'古人学问无遗力，少壮工夫老始成。','陆游《冬夜读书示子聿》'),(308,'三更灯火五更鸡，正是男儿读书时。','颜真卿《劝学诗》'),(309,'李白如今已仙去，月在青天几圆缺？','唐寅《把酒对月歌》'),(310,'天平山上白云泉，云自无心水自闲。','白居易《白云泉》'),(311,'相思相望不相亲，天为谁春。','纳兰性德《画堂春·一生一代一双人》'),(312,'当君怀归日，是妾断肠时。','李白《春思》'),(313,'天阶夜色凉如水，卧看牵牛织女星。','杜牧《秋夕》'),(314,'无情最是台城柳，依旧烟笼十里堤。','韦庄《台城》'),(315,'无言独上西楼，月如钩。寂寞梧桐深院锁清秋。','李煜《相见欢·无言独上西楼》'),(316,'西塞山前白鹭飞，桃花流水鳜鱼肥。','张志和《渔歌子·西塞山前白鹭飞》'),(317,'汴水流，泗水流，流到瓜州古渡头。吴山点点愁。','白居易《长相思·汴水流》'),(318,'小楼昨夜又东风，故国不堪回首月明中。','李煜《虞美人·春花秋月何时了》'),(319,'忽如一夜春风来，千树万树梨花开。','岑参《白雪歌送武判官归京》'),(320,'松树千年终是朽，槿花一日自为荣。','白居易《放言五首·其五》'),(321,'少年听雨歌楼上。红烛昏罗帐。','蒋捷《虞美人·听雨》'),(322,'妆罢低声问夫婿，画眉深浅入时无。','朱庆馀《近试上张籍水部 / 近试上张水部 / 闺意献张水部》'),(323,'红豆生南国，春来发几枝。','王维《相思》'),(324,'迟日江山丽，春风花草香。','杜甫《绝句二首》'),(325,'路漫漫其修远兮，吾将上下而求索。','屈原《离骚》'),(326,'千金纵买相如赋，脉脉此情谁诉。','辛弃疾《摸鱼儿·更能消几番风雨》'),(327,'红颜未老恩先断，斜倚薰笼坐到明。','白居易《后宫词》'),(328,'缺月挂疏桐，漏断人初静。','苏轼《卜算子·黄州定慧院寓居作》'),(329,'昔我往矣，杨柳依依。','佚名《采薇》'),(330,'草木有本心，何求美人折！','张九龄《感遇十二首·其一》'),(331,'欲寄彩笺兼尺素。山长水阔知何处。','晏殊《蝶恋花·槛菊愁烟兰泣露》'),(332,'胜日寻芳泗水滨，无边光景一时新。','朱熹《春日》'),(333,'此生谁料，心在天山，身老沧洲。','陆游《诉衷情·当年万里觅封侯》'),(334,'想当年，金戈铁马，气吞万里如虎。','辛弃疾《永遇乐·京口北固亭怀古》'),(335,'庭前落尽梧桐，水边开彻芙蓉。','朱庭玉《天净沙·秋》'),(336,'昆山玉碎凤凰叫，芙蓉泣露香兰笑。','李贺《李凭箜篌引》'),(337,'一寸相思千万绪。人间没个安排处。','李冠《蝶恋花·春暮》'),(338,'恰同学少年，风华正茂；书生意气，挥斥方遒。','毛泽东《沁园春·长沙》'),(339,'当时明月在，曾照彩云归。','晏几道《临江仙·梦后楼台高锁》'),(340,'今宵酒醒何处？杨柳岸，晓风残月。','柳永《雨霖铃·寒蝉凄切》'),(341,'莫道不销魂，帘卷西风，人比黄花瘦。','李清照《醉花阴·薄雾浓云愁永昼》'),(342,'千古兴亡多少事？悠悠。不尽长江滚滚流。','辛弃疾《南乡子·登京口北固亭有怀》'),(343,'稻花香里说丰年。听取蛙声一片。','辛弃疾《西江月·夜行黄沙道中》'),(344,'云母屏风烛影深，长河渐落晓星沉。','李商隐《嫦娥》'),(345,'荷叶生时春恨生，荷叶枯时秋恨成。','李商隐《暮秋独游曲江》'),(346,'思君如流水，何有穷已时。','徐干《室思》'),(347,'少无适俗韵，性本爱丘山。','陶渊明《归园田居·其一》'),(348,'功名万里外，心事一杯中。','高适《送李侍御赴安西》'),(349,'有情芍药含春泪，无力蔷薇卧晓枝。','秦观《春日》'),(350,'日啖荔枝三百颗，不辞长作岭南人。','苏轼《惠州一绝》'),(351,'宁为百夫长，胜作一书生。','杨炯《从军行》'),(352,'乱花渐欲迷人眼，浅草才能没马蹄。','白居易《钱塘湖春行》'),(353,'少小离家老大回，乡音无改鬓毛衰。','贺知章《回乡偶书二首·其一》'),(354,'枕上诗书闲处好，门前风景雨来佳。','李清照《摊破浣溪沙·病起萧萧两鬓华》'),(355,'停车坐爱枫林晚，霜叶红于二月花。','杜牧《山行》'),(356,'依旧，依旧，人与绿杨俱瘦。','秦观《如梦令·春景》'),(357,'君为女萝草，妾作菟丝花。','李白《古意》'),(358,'丈夫非无泪，不洒离别间。','陆龟蒙《别离》'),(359,'感时花溅泪，恨别鸟惊心。','杜甫《春望》'),(360,'千山鸟飞绝，万径人踪灭。','柳宗元《江雪》'),(361,'花落花开自有时，总赖东君主。','严蕊《卜算子·不是爱风尘》'),(362,'青山相待，白云相爱，梦不到紫罗袍共黄金带。','宋方壶《山坡羊·道情》'),(363,'乱山残雪夜，孤烛异乡人。','崔涂《除夜 / 巴山道中除夜书怀 / 除夜有怀》'),(364,'中秋谁与共孤光。把盏凄然北望。','苏轼《西江月·世事一场大梦》'),(365,'清风明月无人管，并作南楼一味凉。','黄庭坚《鄂州南楼书事》'),(366,'冰雪林中著此身，不同桃李混芳尘；','王冕《白梅》'),(367,'柴门闻犬吠，风雪夜归人。','刘长卿《逢雪宿芙蓉山主人》'),(368,'爆竹声中一岁除，春风送暖入屠苏。','王安石《元日》'),(369,'离别家乡岁月多，近来人事半消磨。','贺知章《回乡偶书二首》'),(370,'一别如斯，落尽梨花月又西。','纳兰性德《采桑子·当时错》'),(371,'为谁醉倒为谁醒，到今犹恨轻离别。','吕本中《踏莎行·雪似梅花》'),(372,'世间行乐亦如此，古来万事东流水。','李白《梦游天姥吟留别 / 别东鲁诸公》'),(373,'孤舟蓑笠翁，独钓寒江雪。','柳宗元《江雪》'),(374,'何处望神州？满眼风光北固楼。','辛弃疾《南乡子·登京口北固亭有怀》'),(375,'欲把西湖比西子，淡妆浓抹总相宜。','苏轼《饮湖上初晴后雨二首·其二》'),(376,'我也不登天子船，我也不上长安眠。','唐寅《把酒对月歌》'),(377,'儿童散学归来早，忙趁东风放纸鸢。','高鼎《村居》'),(378,'衰兰送客咸阳道，天若有情天亦老。','李贺《金铜仙人辞汉歌》'),(379,'一叫一回肠一断，三春三月忆三巴。','李白《宣城见杜鹃花 / 子规》'),(380,'臣心一片磁针石，不指南方不肯休。','文天祥《扬子江》'),(381,'青鸟不传云外信，丁香空结雨中愁。','李璟《摊破浣溪沙·手卷真珠上玉钩》'),(382,'日暮苍山远，天寒白屋贫。','刘长卿《逢雪宿芙蓉山主人》'),(383,'娶妻无媒毋须恨，书中有女颜如玉。','赵恒《劝学诗》'),(384,'鸟宿池边树，僧敲月下门。','贾岛《题李凝幽居》'),(385,'寒夜客来茶当酒，竹炉汤沸火初红。','杜耒《寒夜》'),(386,'草长莺飞二月天，拂堤杨柳醉春烟。','高鼎《村居》'),(387,'风吹柳花满店香，吴姬压酒唤客尝。','李白《金陵酒肆留别》'),(388,'人生得意须尽欢，莫使金樽空对月。','李白《将进酒》'),(389,'清明时节雨纷纷，路上行人欲断魂。','杜牧《清明》'),(390,'卧看满天云不动，不知云与我俱东。','陈与义《襄邑道中》'),(391,'星垂平野阔，月涌大江流。','杜甫《旅夜书怀》'),(392,'秋风起兮白云飞，草木黄落兮雁南归。','刘彻《秋风辞》'),(393,'我寄愁心与明月，随风直到夜郎西。','李白《闻王昌龄左迁龙标遥有此寄》'),(394,'黄河远上白云间，一片孤城万仞山。','王之涣《凉州词二首·其一》'),(395,'鹅湖山下稻粱肥，豚栅鸡栖半掩扉。','王驾《社日》'),(396,'梧桐叶上三更雨，叶叶声声是别离。','周紫芝《鹧鸪天·一点残红欲尽时》'),(397,'漠漠水田飞白鹭，阴阴夏木啭黄鹂。','王维《积雨辋川庄作 / 秋归辋川庄作》'),(398,'南国有佳人，容华若桃李。','曹植《杂诗·南国有佳人》'),(399,'千锤万凿出深山，烈火焚烧若等闲。','于谦《石灰吟》'),(400,'恨君不似江楼月，南北东西，南北东西，只有相随无别离。','吕本中《采桑子·恨君不似江楼月》'),(401,'感君缠绵意，系在红罗襦。','张籍《节妇吟·寄东平李司空师道》'),(402,'谁料同心结不成，翻就相思结。','夏完淳《卜算子·秋色到空闺》'),(403,'国破山河在，城春草木深。','杜甫《春望》'),(404,'生当作人杰，死亦为鬼雄。','李清照《夏日绝句》'),(405,'一壶酒，一竿身，快活如侬有几人。','李煜《渔父·浪花有意千里雪》'),(406,'海棠未雨，梨花先雪，一半春休。','王雱《眼儿媚·杨柳丝丝弄轻柔》'),(407,'随风潜入夜，润物细无声。','杜甫《春夜喜雨》'),(408,'人世几回伤往事，山形依旧枕寒流。','刘禹锡《西塞山怀古》'),(409,'草木也知愁，韶华竟白头。','曹雪芹《唐多令·柳絮》'),(410,'及时当勉励，岁月不待人。','陶渊明《杂诗·人生无根蒂》'),(411,'春城无处不飞花，寒食东风御柳斜。','韩翃《寒食 / 寒食日即事》'),(412,'壮心未与年俱老，死去犹能作鬼雄。','陆游《书愤五首·其二》'),(413,'春色满园关不住，一枝红杏出墙来。','叶绍翁《游园不值》'),(414,'看朱成碧思纷纷，憔悴支离为忆君。','武则天《如意娘》'),(415,'日照香炉生紫烟，遥看瀑布挂前川。','李白《望庐山瀑布》'),(416,'桃花潭水深千尺，不及汪伦送我情。','李白《赠汪伦》'),(417,'但使龙城飞将在，不教胡马度阴山。','王昌龄《出塞二首》'),(418,'举杯邀明月，对影成三人。','李白《月下独酌四首·其一》'),(419,'愿君多采撷，此物最相思。','王维《相思》'),(420,'长恨此身非我有，何时忘却营营。','苏轼《临江仙·夜饮东坡醒复醉》'),(421,'纵被无情弃，不能羞。','韦庄《思帝乡·春日游》'),(422,'晚日寒鸦一片愁。柳塘新绿却温柔。','辛弃疾《鹧鸪天·晚日寒鸦一片愁》'),(423,'三十功名尘与土，八千里路云和月。','岳飞《满江红·写怀》'),(424,'怒发冲冠，凭栏处、潇潇雨歇。','岳飞《满江红·写怀》'),(425,'花褪残红青杏小。燕子飞时，绿水人家绕。','苏轼《蝶恋花·春景》'),(426,'燕子来时新社，梨花落后清明。','晏殊《破阵子·春景》'),(427,'自古逢秋悲寂寥，我言秋日胜春朝。','刘禹锡《秋词》'),(428,'我欲穿花寻路，直入白云深处，浩气展虹霓。','黄庭坚《水调歌头·游览》'),(429,'皑如山上雪，皎若云间月。','卓文君《白头吟》'),(430,'江山代有才人出，各领风骚数百年。','赵翼《论诗五首·其二》'),(431,'迢迢牵牛星，皎皎河汉女。','佚名《迢迢牵牛星》'),(432,'浮生只合尊前老。雪满长安道。','舒亶《虞美人·寄公度》'),(433,'峨眉山月半轮秋，影入平羌江水流。','李白《峨眉山月歌》'),(434,'醉翁之意不在酒，在乎山水之间也。','欧阳修《醉翁亭记》'),(435,'四十年来家国，三千里地山河。','李煜《破阵子·四十年来家国》'),(436,'殷勤花下同携手。更尽杯中酒。美人不用敛蛾眉。','叶梦得《虞美人·雨后同干誉才卿置酒来禽花下作》'),(437,'黑云翻墨未遮山，白雨跳珠乱入船。','苏轼《六月二十七日望湖楼醉书》'),(438,'相看两不厌，只有敬亭山。','李白《独坐敬亭山》'),(439,'一片春愁待酒浇。江上舟摇，楼上帘招。','蒋捷《一剪梅·舟过吴江》'),(440,'只解沙场为国死，何须马革裹尸还。','徐锡麟《出塞》'),(441,'野径云俱黑，江船火独明。','杜甫《春夜喜雨》'),(442,'若似月轮终皎洁，不辞冰雪为卿热。','纳兰性德《蝶恋花·辛苦最怜天上月》'),(443,'池上碧苔三四点，叶底黄鹂一两声。','晏殊《破阵子·春景》'),(444,'袅袅城边柳，青青陌上桑。','张仲素《春闺思》'),(445,'遥想公瑾当年，小乔初嫁了，雄姿英发。','苏轼《念奴娇·赤壁怀古》'),(446,'儿童急走追黄蝶，飞入菜花无处寻。','杨万里《宿新市徐公店》'),(447,'了却君王天下事，赢得生前身后名。','辛弃疾《破阵子·为陈同甫赋壮词以寄之》'),(448,'明月出天山，苍茫云海间。','李白《关山月》'),(449,'梅花雪，梨花月，总相思。','张惠言《相见欢·年年负却花期》'),(450,'一别都门三改火，天涯踏尽红尘。','苏轼《临江仙·送钱穆父》'),(451,'鸟向平芜远近，人随流水东西。','刘长卿《谪仙怨·晴川落日初低》'),(452,'素衣莫起风尘叹，犹及清明可到家。','陆游《临安春雨初霁》'),(453,'众里寻他千百度。蓦然回首，那人却在，灯火阑珊处。','辛弃疾《青玉案·元夕》'),(454,'明月不谙离恨苦。斜光到晓穿朱户。','晏殊《蝶恋花·槛菊愁烟兰泣露》'),(455,'羡青山有思，白鹤忘机。','汤恢《八声甘州·摘青梅荐酒》'),(456,'远上寒山石径斜，白云生处有人家。','杜牧《山行》'),(457,'家国兴亡自有时，吴人何苦怨西施。','罗隐《西施》'),(458,'天下英雄谁敌手？曹刘。生子当如孙仲谋。','辛弃疾《南乡子·登京口北固亭有怀》'),(459,'死去元知万事空，但悲不见九州同。','陆游《示儿》'),(460,'众鸟高飞尽，孤云独去闲。','李白《独坐敬亭山》'),(461,'黄鹤一去不复返，白云千载空悠悠。','崔颢《黄鹤楼 / 登黄鹤楼》'),(462,'范增一去无谋主，韩信原来是逐臣。','严遂成《乌江项王庙》'),(463,'风乍起，吹皱一池春水。','冯延巳《谒金门·风乍起》'),(464,'花门楼前见秋草，岂能贫贱相看老。','岑参《凉州馆中与诸判官夜集》'),(465,'暖风熏得游人醉，直把杭州作汴州。','林升《题临安邸》'),(466,'不畏浮云遮望眼，只缘身在最高层。','王安石《登飞来峰》'),(467,'北国风光，千里冰封，万里雪飘。','毛泽东《沁园春·雪》'),(468,'野旷天低树，江清月近人。','孟浩然《宿建德江》'),(469,'相见争如不见，多情何似无情。','司马光《西江月·宝髻松松挽就》'),(470,'烟笼寒水月笼沙，夜泊秦淮近酒家。','杜牧《泊秦淮》'),(471,'唯有门前镜湖水，春风不改旧时波。','贺知章《回乡偶书二首》'),(472,'忽忆故人今总老。贪梦好。茫然忘了邯郸道。','王安石《渔家傲·平岸小桥千嶂抱》'),(473,'轻汗微微透碧纨，明朝端午浴芳兰。','苏轼《浣溪沙·端午》'),(474,'年年岁岁花相似，岁岁年年人不同。','刘希夷《代悲白头翁 / 白头吟 / 有所思》'),(475,'恰如灯下，故人万里，归来对影。','黄庭坚《品令·茶词》'),(476,'昔时人已没，今日水犹寒。','骆宾王《于易水送人 / 于易水送别》'),(477,'千里莺啼绿映红，水村山郭酒旗风。','杜牧《江南春》'),(478,'谁道人生无再少？门前流水尚能西！休将白发唱黄鸡。','苏轼《浣溪沙·游蕲水清泉寺》'),(479,'青山隐隐水迢迢，秋尽江南草未凋。','杜牧《寄扬州韩绰判官》'),(480,'半生已分孤眠过，山枕檀痕涴。','纳兰性德《虞美人·曲阑深处重相见》'),(481,'朝辞白帝彩云间，千里江陵一日还。','李白《早发白帝城 / 白帝下江陵》'),(482,'连雨不知春去，一晴方觉夏深。','范成大《喜晴》'),(483,'少壮不努力，老大徒伤悲！','佚名《长歌行》'),(484,'有梅无雪不精神，有雪无诗俗了人。','卢梅坡《雪梅·其二》'),(485,'风雨替花愁。风雨罢，花也应休。','赵秉文《青杏儿·风雨替花愁》'),(486,'居高声自远，非是藉秋风。','虞世南《蝉》'),(487,'黄梅时节家家雨，青草池塘处处蛙。','赵师秀《约客 / 有约》'),(488,'绿树阴浓夏日长，楼台倒影入池塘。','高骈《山亭夏日》'),(489,'春日游，杏花吹满头。','韦庄《思帝乡·春日游》'),(490,'一重山，两重山。山远天高烟水寒，相思枫叶丹。','李煜《长相思·一重山》'),(491,'君若清路尘，妾若浊水泥；','曹植《明月上高楼》'),(492,'春未绿，鬓先丝。人间别久不成悲。','姜夔《鹧鸪天·元夕有所梦》'),(493,'醉别西楼醒不记。春梦秋云，聚散真容易。','晏几道《蝶恋花·醉别西楼醒不记》'),(494,'朝看水东流，暮看日西坠。','钱福《明日歌》'),(495,'几处早莺争暖树，谁家新燕啄春泥。','白居易《钱塘湖春行》'),(496,'别来春半，触目柔肠断。','李煜《清平乐·别来春半》'),(497,'欲将轻骑逐，大雪满弓刀。','卢纶《和张仆射塞下曲·其三》'),(498,'此夜曲中闻折柳，何人不起故园情。','李白《春夜洛城闻笛 / 春夜洛阳城闻笛》'),(499,'且就洞庭赊月色，将船买酒白云边。','李白《游洞庭湖五首·其二》'),(500,'九州生气恃风雷，万马齐喑究可哀。','龚自珍《己亥杂诗·其二百二十》'),(501,'零落成泥碾作尘，只有香如故。','陆游《卜算子·咏梅》'),(502,'青青园中葵，朝露待日晞。','佚名《长歌行》'),(503,'千磨万击还坚劲，任尔东西南北风。','郑燮《竹石》'),(504,'海日生残夜，江春入旧年。','王湾《次北固山下》'),(505,'年年岁岁望中秋，岁岁年年雾雨愁。','曾几《癸未八月十四日至十六夜月色皆佳》'),(506,'三分春色二分愁，更一分风雨。','叶清臣《贺圣朝·留别》'),(507,'只有天在上，更无山与齐。','寇准《咏华山》'),(508,'敕勒川，阴山下。天似穹庐，笼盖四野。','佚名《敕勒歌》'),(509,'问渠哪得清如许？为有源头活水来。','朱熹《活水亭观书有感二首·其一》'),(510,'诚知此恨人人有，贫贱夫妻百事哀。','元稹《遣悲怀三首·其二》'),(511,'春草明年绿，王孙归不归？','王维《送别 / 山中送别 / 送友》'),(512,'锄禾日当午，汗滴禾下土。','李绅《古风二首 / 悯农二首》'),(513,'不是花中偏爱菊，此花开尽更无花。','元稹《菊花》'),(514,'君不见走马川行雪海边，平沙莽莽黄入天。','岑参《走马川行奉送出师西征 / 走马川行奉送封大夫出师西征》'),(515,'人间万事，毫发常重泰山轻。','辛弃疾《水调歌头·壬子三山被召陈端仁给事饮饯席上作》'),(516,'一向年光有限身。等闲离别易销魂。酒筵歌席莫辞频。','晏殊《浣溪沙·一向年光有限身》'),(517,'一年将尽夜，万里未归人。','戴叔伦《除夜宿石头驿》'),(518,'雪消门外千山绿，花发江边二月晴。','欧阳修《春日西湖寄谢法曹歌》'),(519,'聚散匆匆，此恨年年有。','魏夫人《点绛唇·波上清风》'),(520,'驿外断桥边，寂寞开无主。','陆游《卜算子·咏梅》'),(521,'塞下秋来风景异，衡阳雁去无留意。','范仲淹《渔家傲·秋思》'),(522,'衣带渐宽终不悔，为伊消得人憔悴。','柳永《蝶恋花·伫倚危楼风细细》'),(523,'碧玉妆成一树高，万条垂下绿丝绦。','贺知章《咏柳 / 柳枝词》'),(524,'燕子不归春事晚，一汀烟雨杏花寒。','戴叔伦《苏溪亭》'),(525,'酒贱常愁客少，月明多被云妨。','苏轼《西江月·世事一场大梦》'),(526,'黄昏庭院柳啼鸦，记得那人，和月折梨花。','陈亮《虞美人·东风荡飏轻云缕》'),(527,'一种相思，两处闲愁。','李清照《一剪梅·红藕香残玉簟秋》'),(528,'白日依山尽，黄河入海流。','王之涣《登鹳雀楼》'),(529,'窗含西岭千秋雪，门泊东吴万里船。','杜甫《绝句》'),(530,'林暗草惊风，将军夜引弓。','卢纶《和张仆射塞下曲·其二》'),(531,'山河破碎风飘絮，身世浮沉雨打萍。','文天祥《过零丁洋》'),(532,'去年元夜时，花市灯如昼。','欧阳修《生查子·元夕》'),(533,'暗暗淡淡紫，融融冶冶黄。','李商隐《菊花》'),(534,'此生此夜不长好，明月明年何处看。','苏轼《阳关曲 / 中秋月》'),(535,'浮云终日行，游子久不至。','杜甫《梦李白二首·其二》'),(536,'难相见，易相别，又是玉楼花似雪。','韦庄《应天长·别来半岁音书绝》'),(537,'九曲黄河万里沙，浪淘风簸自天涯。','刘禹锡《浪淘沙·九曲黄河万里沙》'),(538,'忆君心似西江水，日夜东流无歇时。','鱼玄机《江陵愁望寄子安》'),(539,'两鬓可怜青，只为相思老。','晏几道《生查子·关山魂梦长》'),(540,'独自凄凉还自遣，自制离愁。','龚自珍《浪淘沙·写梦》'),(541,'有情不管别离久。情在相逢终有。','晏几道《秋蕊香·池苑清阴欲就》'),(542,'总为浮云能蔽日，长安不见使人愁。','李白《登金陵凤凰台》'),(543,'还卿一钵无情泪，恨不相逢未剃时。','苏曼殊《本事诗十首·选二》'),(544,'欲写彩笺书别怨。泪痕早已先书满。','晏几道《蝶恋花·黄菊开时伤聚散》'),(545,'青青子衿，悠悠我心。','佚名《子衿》'),(546,'多情却似总无情，唯觉樽前笑不成。','杜牧《赠别》'),(547,'家在梦中何日到，春来江上几人还？','卢纶《长安春望》'),(548,'今夜月明人尽望，不知秋思落谁家。','王建《十五夜望月寄杜郎中》'),(549,'琵琶弦上说相思。当时明月在，曾照彩云归。','晏几道《临江仙·梦后楼台高锁》'),(550,'相思似海深，旧事如天远。','乐婉《卜算子·答施》'),(551,'惟将终夜常开眼，报答平生未展眉。','元稹《遣悲怀三首·其三》'),(552,'山随平野尽，江入大荒流。','李白《渡荆门送别》'),(553,'平林漠漠烟如织，寒山一带伤心碧。','李白《菩萨蛮·平林漠漠烟如织》'),(554,'千里黄云白日曛，北风吹雁雪纷纷。','高适《别董大二首》'),(555,'云淡风轻近午天，傍花随柳过前川。','程颢《春日偶成·云淡风轻近午天》'),(556,'白发悲花落，青云羡鸟飞。','岑参《寄左省杜拾遗》'),(557,'东风不与周郎便，铜雀春深锁二乔。','杜牧《赤壁》'),(558,'最是一年春好处，绝胜烟柳满皇都。','韩愈《早春呈水部张十八员外 / 初春小雨 / 早春》'),(559,'银烛秋光冷画屏，轻罗小扇扑流萤。','杜牧《秋夕》'),(560,'花似伊。柳似伊。花柳青春人别离。','欧阳修《长相思·花似伊》'),(561,'谁教岁岁红莲夜，两处沉吟各自知。','姜夔《鹧鸪天·元夕有所梦》'),(562,'知有儿童挑促织，夜深篱落一灯明。','叶绍翁《夜书所见》'),(563,'高楼目尽欲黄昏，梧桐叶上萧萧雨。','晏殊《踏莎行·碧海无波》'),(564,'一月不读书，耳目失精爽。','萧抡谓《读书有所见作》'),(565,'此去经年，应是良辰好景虚设。','柳永《雨霖铃·寒蝉凄切》'),(566,'沧浪之水清兮，可以濯我缨；','佚名《沧浪歌》'),(567,'相寻梦里路，飞雨落花中。','晏几道《临江仙·斗草阶前初见》'),(568,'垂死病中惊坐起，暗风吹雨入寒窗。','元稹《闻乐天授江州司马》'),(569,'江涵秋影雁初飞，与客携壶上翠微。','杜牧《九日齐山登高》'),(570,'西风多少恨，吹不散眉弯。','纳兰性德《临江仙·寒柳》'),(571,'暮云收尽溢清寒。银汉无声转玉盘。','苏轼《阳关曲 / 中秋月》'),(572,'云横秦岭家何在？雪拥蓝关马不前。','韩愈《左迁至蓝关示侄孙湘》'),(573,'寒雨连天夜入吴，平明送客楚山孤。','王昌龄《芙蓉楼送辛渐二首》'),(574,'绿遍山原白满川，子规声里雨如烟。','翁卷《乡村四月》'),(575,'风烟俱净，天山共色。','吴均《与朱元思书》'),(576,'冰，水为之，而寒于水。','荀子《劝学》'),(577,'洛阳城里春光好，洛阳才子他乡老。','韦庄《菩萨蛮》'),(578,'日暮乡关何处是？烟波江上使人愁。','崔颢《黄鹤楼 / 登黄鹤楼》'),(579,'柳条折尽花飞尽，借问行人归不归？','佚名《送别诗》'),(580,'杜鹃再拜忧天泪，精卫无穷填海心。','黄遵宪《赠梁任父母同年 / 题梁任父同年》'),(581,'冠盖满京华，斯人独憔悴。','杜甫《梦李白二首·其二》'),(582,'晓看红湿处，花重锦官城。','杜甫《春夜喜雨》'),(583,'移舟去。未成新句。一砚梨花雨。','周晋《点绛唇·访牟存叟南漪钓隐》'),(584,'梅子金黄杏子肥，麦花雪白菜花稀。','范成大《四时田园杂兴·其二》'),(585,'愁肠已断无由醉，酒未到，先成泪。','范仲淹《御街行·秋日怀旧》'),(586,'浮云游子意，落日故人情。','李白《送友人》'),(587,'故人入我梦，明我长相忆。','杜甫《梦李白二首·其一》'),(588,'唯愿当歌对酒时，月光长照金樽里。','李白《把酒问月·故人贾淳令予问之》'),(589,'梧桐树，三更雨，不道离情正苦。','温庭筠《更漏子·玉炉香》'),(590,'欲渡黄河冰塞川，将登太行雪满山。','李白《行路难·其一》'),(591,'姑苏城外寒山寺，夜半钟声到客船。','张继《枫桥夜泊 / 夜泊枫江》'),(592,'郁孤台下清江水，中间多少行人泪？','辛弃疾《菩萨蛮·书江西造口壁》'),(593,'低头弄莲子，莲子清如水。','佚名《西洲曲》'),(594,'三万里河东入海，五千仞岳上摩天。','陆游《秋夜将晓出篱门迎凉有感》'),(595,'闲云潭影日悠悠，物换星移几度秋。','王勃《滕王阁序》'),(596,'秋风萧瑟天气凉，草木摇落露为霜，群燕辞归鹄南翔。','曹丕《燕歌行二首·其一》'),(597,'月黑见渔灯，孤光一点萤。','查慎行《舟夜书所见》'),(598,'洛阳城东桃李花，飞来飞去落谁家？','刘希夷《代悲白头翁 / 白头吟 / 有所思》'),(599,'二十余年如一梦，此身虽在堪惊。','陈与义《临江仙·夜登小阁忆洛中旧游》'),(600,'彩线轻缠红玉臂，小符斜挂绿云鬟。佳人相见一千年。','苏轼《浣溪沙·端午》'),(601,'桃花春色暖先开，明媚谁人不看来。','周朴《桃花》'),(602,'一朵芙蕖，开过尚盈盈。','苏轼《江神子·江景》'),(603,'明月楼高休独倚。酒入愁肠，化作相思泪。','范仲淹《苏幕遮·怀旧》'),(604,'一夜雨声凉到梦，万荷叶上送秋来。','陈文述《夏日杂诗》'),(605,'东武望余杭，云海天涯两渺茫。','苏轼《南乡子·和杨元素时移守密州》'),(606,'沙上并禽池上暝。云破月来花弄影。','张先《天仙子·水调数声持酒听》'),(607,'细雨鱼儿出，微风燕子斜。','杜甫《水槛遣心二首》'),(608,'今我来思，雨雪霏霏。','佚名《采薇》'),(609,'离多最是，东西流水，终解两相逢。','晏几道《少年游·离多最是》'),(610,'深知身在情长在，怅望江头江水声。','李商隐《暮秋独游曲江》'),(611,'江流天地外，山色有无中。','王维《汉江临泛 / 汉江临眺》'),(612,'山不厌高，海不厌深。','曹操《短歌行》'),(613,'两岸猿声啼不住，轻舟已过万重山。','李白《早发白帝城 / 白帝下江陵》'),(614,'若有知音见采，不辞遍唱阳春。','晏殊《山亭柳·赠歌者》'),(615,'凄凉别后两应同，最是不胜清怨月明中。','纳兰性德《虞美人·曲阑深处重相见》'),(616,'杨花榆荚无才思，惟解漫天作雪飞。','韩愈《晚春》'),(617,'谁谓伤心画不成，画人心逐世人情。','韦庄《金陵图》'),(618,'三千丈清愁鬓发，五十年春梦繁华。','乔吉《折桂令·客窗清明》'),(619,'渭城朝雨浥轻尘，客舍青青柳色新。','王维《渭城曲 / 送元二使安西》'),(620,'读书破万卷，下笔如有神。','杜甫《奉赠韦左丞丈二十二韵》'),(621,'十年无梦得还家，独立青峰野水涯。','谢枋得《武夷山中》'),(622,'千里江山寒色远，芦花深处泊孤舟，笛在月明楼。','李煜《望江南·闲梦远》'),(623,'王师北定中原日，家祭无忘告乃翁。','陆游《示儿》'),(624,'悲欢离合总无情。一任阶前、点滴到天明。','蒋捷《虞美人·听雨》'),(625,'扬子江头杨柳春，杨花愁杀渡江人。','郑谷《淮上与友人别》'),(626,'两句三年得，一吟双泪流。','贾岛《题诗后》'),(627,'浊酒一杯家万里，燕然未勒归无计。','范仲淹《渔家傲·秋思》'),(628,'遥知兄弟登高处，遍插茱萸少一人。','王维《九月九日忆山东兄弟 / 九月九忆山东兄弟》'),(629,'相思本是无凭语，莫向花笺费泪行。','晏几道《鹧鸪天·醉拍春衫惜旧香》'),(630,'青海长云暗雪山，孤城遥望玉门关。','王昌龄《从军行七首·其四》'),(631,'天门中断楚江开，碧水东流至此回。','李白《望天门山》'),(632,'仍怜故乡水，万里送行舟。','李白《渡荆门送别》'),(633,'叶上初阳干宿雨、水面清圆，一一风荷举。','周邦彦《苏幕遮·燎沉香》'),(634,'梅子留酸软齿牙，芭蕉分绿与窗纱。','杨万里《闲居初夏午睡起》'),(635,'庭树不知人去尽，春来还发旧时花。','岑参《山房春事二首》'),(636,'共眠一舸听秋雨，小簟轻衾各自寒。','朱彝尊《桂殿秋·思往事》'),(637,'兴尽晚回舟，误入藕花深处。','李清照《如梦令·常记溪亭日暮》'),(638,'清谈可以饱，梦想接无由。','韩愈《洞庭湖阻风赠张十一署·时自阳山徙掾江陵》'),(639,'牧童归去横牛背，短笛无腔信口吹。','雷震《村晚》'),(640,'蓬头稚子学垂纶，侧坐莓苔草映身。','胡令能《小儿垂钓》'),(641,'牧童骑黄牛，歌声振林樾。','袁枚《所见》'),(642,'残星几点雁横塞，长笛一声人倚楼。','赵嘏《长安晚秋 / 秋望 / 秋夕》'),(643,'月出惊山鸟，时鸣春涧中。','王维《鸟鸣涧》'),(644,'纸屏石枕竹方床，手倦抛书午梦长。','蔡确《夏日登车盖亭》'),(645,'登高壮观天地间，大江茫茫去不还。','李白《庐山谣寄卢侍御虚舟》'),(646,'落木千山天远大，澄江一道月分明。','黄庭坚《登快阁》'),(647,'别来半岁音书绝，一寸离肠千万结。','韦庄《应天长·别来半岁音书绝》'),(648,'江南春尽离肠断，苹满汀洲人未归。','寇准《江南春·波渺渺》'),(649,'当时轻别意中人，山长水远知何处。','晏殊《踏莎行·碧海无波》'),(650,'梦回人远许多愁，只在梨花风雨处。','辛弃疾《玉楼春·风前欲劝春光住》'),(651,'楼船夜雪瓜洲渡，铁马秋风大散关。','陆游《书愤五首·其一》'),(652,'千古江山，英雄无觅，孙仲谋处。','辛弃疾《永遇乐·京口北固亭怀古》'),(653,'酒债寻常行处有，人生七十古来稀。','杜甫《曲江二首》'),(654,'笑尽一杯酒，杀人都市中。','李白《结客少年场行》'),(655,'宫女如花满春殿，只今惟有鹧鸪飞。','李白《越中览古》'),(656,'都道无人愁似我，今夜雪，有梅花，似我愁。','蒋捷《梅花引·荆溪阻雪》'),(657,'芳树无人花自落，春山一路鸟空啼。','李华《春行即兴》'),(658,'日暮酒醒人已远，满天风雨下西楼。','许浑《谢亭送别》'),(659,'春来秋去相思在，秋去春来信息稀。','鱼玄机《闺怨》'),(660,'知君用心如日月，事夫誓拟同生死。','张籍《节妇吟·寄东平李司空师道》'),(661,'斑竹枝，斑竹枝，泪痕点点寄相思。','刘禹锡《潇湘神·斑竹枝》'),(662,'凉月如眉挂柳湾，越中山色镜中看。','戴叔伦《兰溪棹歌》'),(663,'昨夜雨疏风骤，浓睡不消残酒。','李清照《如梦令·昨夜雨疏风骤》'),(664,'纤云弄巧，飞星传恨，银汉迢迢暗度。','秦观《鹊桥仙·纤云弄巧》'),(665,'涉江采芙蓉，兰泽多芳草。','佚名《涉江采芙蓉》'),(666,'杨柳阴阴细雨晴，残花落尽见流莺。','武元衡《春兴》'),(667,'朱弦已为佳人绝，青眼聊因美酒横。','黄庭坚《登快阁》'),(668,'人家见生男女好，不知男女催人老。','王建《短歌行》'),(669,'令公桃李满天下，何用堂前更种花。','白居易《奉和令公绿野堂种花》'),(670,'寻常一样窗前月，才有梅花便不同。','杜耒《寒夜》'),(671,'殷勤昨夜三更雨，又得浮生一日凉。','苏轼《鹧鸪天·林断山明竹隐墙》'),(672,'冰骨清寒瘦一枝。玉人初上木兰时。','吴文英《浣溪沙·题李中斋舟中梅屏》'),(673,'待到重阳日，还来就菊花。','孟浩然《过故人庄》'),(674,'小娃撑小艇，偷采白莲回。','白居易《池上》'),(675,'十年种木，一年种谷，都付儿童。','元好问《人月圆·重冈已隔红尘断》'),(676,'穷且益坚，不坠青云之志。','王勃《滕王阁序》'),(677,'一曲新词酒一杯，去年天气旧亭台。','晏殊《浣溪沙·一曲新词酒一杯》'),(678,'晚年唯好静，万事不关心。','王维《酬张少府》'),(679,'帘外雨潺潺，春意阑珊。','李煜《浪淘沙令·帘外雨潺潺》'),(680,'未觉池塘春草梦，阶前梧叶已秋声。','朱熹《偶成》'),(681,'春山烟欲收，天淡星稀小。','牛希济《生查子·春山烟欲收》'),(682,'有三秋桂子，十里荷花。','柳永《望海潮·东南形胜》'),(683,'尘世难逢开口笑，菊花须插满头归。','杜牧《九日齐山登高》'),(684,'泰山不要欺毫末，颜子无心羡老彭。','白居易《放言五首·其五》'),(685,'雪纷纷，掩重门，不由人不断魂，瘦损江梅韵。','关汉卿《大德歌·冬》'),(686,'好风凭借力，送我上青云。','曹雪芹《临江仙·柳絮》'),(687,'客路青山外，行舟绿水前。','王湾《次北固山下》'),(688,'空山不见人，但闻人语响。','王维《鹿柴》'),(689,'青山遮不住，毕竟东流去。','辛弃疾《菩萨蛮·书江西造口壁》'),(690,'故不登高山，不知天之高也；不临深溪，不知地之厚也；','荀子《劝学》'),(691,'相思一夜情多少，地角天涯未是长。','张仲素《燕子楼诗三首》'),(692,'夜夜相思更漏残，伤心明月凭阑干，想君思我锦衾寒。','韦庄《浣溪沙·夜夜相思更漏残》'),(693,'四海皆兄弟，谁为行路人。','佚名《旧题苏武诗 / 别诗四首·其一》'),(694,'待浮花、浪蕊都尽，伴君幽独。','苏轼《贺新郎·夏景》'),(695,'共看明月应垂泪，一夜乡心五处同。','白居易《望月有感》'),(696,'东篱把酒黄昏后，有暗香盈袖。','李清照《醉花阴·薄雾浓云愁永昼》'),(697,'江雨霏霏江草齐，六朝如梦鸟空啼。','韦庄《台城》'),(698,'梦断香消四十年，沈园柳老不吹绵。','陆游《沈园二首》'),(699,'历览前贤国与家，成由勤俭破由奢。','李商隐《咏史二首·其二》'),(700,'富贵必从勤苦得，男儿须读五车书。','杜甫《柏学士茅屋》'),(701,'鸡声茅店月，人迹板桥霜。','温庭筠《商山早行》'),(702,'遥知湖上一樽酒，能忆天涯万里人。','欧阳修《春日西湖寄谢法曹歌》'),(703,'对酒卷帘邀明月，风露透窗纱。','苏轼《少年游·润州作》'),(704,'柳絮风轻，梨花雨细。','谢逸《踏莎行·柳絮风轻》'),(705,'关关雎鸠，在河之洲。窈窕淑女，君子好逑。','佚名《关雎》'),(706,'独坐幽篁里，弹琴复长啸。','王维《竹里馆》'),(707,'不知细叶谁裁出，二月春风似剪刀。','贺知章《咏柳 / 柳枝词》'),(708,'移舟泊烟渚，日暮客愁新。','孟浩然《宿建德江》'),(709,'何日归家洗客袍？银字笙调，心字香烧。','蒋捷《一剪梅·舟过吴江》'),(710,'君自故乡来，应知故乡事。','王维《杂诗三首·其二》'),(711,'孤帆远影碧空尽，唯见长江天际流。','李白《黄鹤楼送孟浩然之广陵》'),(712,'四月十七，正是去年今日，别君时。','韦庄《女冠子·四月十七》'),(713,'孤山寺北贾亭西，水面初平云脚低。','白居易《钱塘湖春行》'),(714,'寒雨连江夜入吴，平明送客楚山孤。','王昌龄《芙蓉楼送辛渐》'),(715,'万壑树参天，千山响杜鹃。','王维《送梓州李使君》'),(716,'招魂楚些何嗟及，山鬼暗啼风雨。','元好问《摸鱼儿·雁丘词 / 迈陂塘》'),(717,'流水便随春远，行云终与谁同。','晏几道《临江仙·斗草阶前初见》'),(718,'雨里鸡鸣一两家，竹溪村路板桥斜。','王建《雨过山村》'),(719,'月下飞天镜，云生结海楼。','李白《渡荆门送别》'),(720,'黑云压城城欲摧，甲光向日金鳞开。','李贺《雁门太守行》'),(721,'野火烧不尽，春风吹又生。','白居易《草 / 赋得古原草送别》'),(722,'不积小流，无以成江海。','荀子《劝学》'),(723,'兰叶春葳蕤，桂华秋皎洁。','张九龄《感遇十二首·其一》'),(724,'莫笑农家腊酒浑，丰年留客足鸡豚。','陆游《游山西村》'),(725,'新丰美酒斗十千，咸阳游侠多少年。','王维《少年行四首》'),(726,'假金方用真金镀，若是真金不镀金。','李绅《答章孝标》'),(727,'童孙未解供耕织，也傍桑阴学种瓜。','范成大《夏日田园杂兴·其七》'),(728,'独上江楼思渺然，月光如水水如天。','赵嘏《江楼旧感》'),(729,'青女素娥俱耐冷，月中霜里斗婵娟。','李商隐《霜月》'),(730,'月黑雁飞高，单于夜遁逃。','卢纶《和张仆射塞下曲·其三》'),(731,'深林人不知，明月来相照。','王维《竹里馆》'),(732,'捐躯赴国难，视死忽如归！','曹植《白马篇》'),(733,'少年易学老难成，一寸光阴不可轻。','朱熹《偶成》'),(734,'今夜偏知春气暖，虫声新透绿窗纱。','刘方平《夜月 / 月夜》'),(735,'一畦春韭绿，十里稻花香。','曹雪芹《菱荇鹅儿水》'),(736,'绿杨芳草长亭路。年少抛人容易去。','晏殊《玉楼春·春恨》'),(737,'满载一船秋色，平铺十里湖光。','张孝祥《西江月·阻风山峰下》'),(738,'东风袅袅泛崇光，香雾空蒙月转廊。','苏轼《海棠·东风袅袅泛崇光》'),(739,'春水满四泽，夏云多奇峰。','陶渊明《四时》'),(740,'明日隔山岳，世事两茫茫。','杜甫《赠卫八处士》'),(741,'过尽千帆皆不是，斜晖脉脉水悠悠。','温庭筠《望江南·梳洗罢》'),(742,'不论平地与山尖，无限风光尽被占。','罗隐《蜂》'),(743,'忆昔花间相见后，只凭纤手，暗抛红豆。','欧阳炯《贺明朝·忆昔花间相见后》'),(744,'怅恨不逢如意酒。寻思难值有情人。','晏几道《浣溪沙·闲弄筝弦懒系裙》'),(745,'狂风吹我心，西挂咸阳树。','李白《金乡送韦八之西京》'),(746,'不知何处吹芦管，一夜征人尽望乡。','李益《夜上受降城闻笛》'),(747,'世事茫茫难自料，春愁黯黯独成眠。','韦应物《寄李儋元锡》'),(748,'羌管悠悠霜满地，人不寐，将军白发征夫泪。','范仲淹《渔家傲·秋思》'),(749,'庭院深深深几许，杨柳堆烟，帘幕无重数。','欧阳修《蝶恋花·庭院深深深几许》'),(750,'笑杀陶渊明，不饮杯中酒。','李白《嘲王历阳不肯饮酒》'),(751,'胜败兵家事不期，包羞忍耻是男儿。','杜牧《题乌江亭》'),(752,'飘飘何所似，天地一沙鸥。','杜甫《旅夜书怀》'),(753,'揉蓝衫子杏黄裙，独倚玉阑无语点檀唇。','秦观《南歌子·香墨弯弯画》'),(754,'白雪却嫌春色晚，故穿庭树作飞花。','韩愈《春雪》'),(755,'留连戏蝶时时舞，自在娇莺恰恰啼。','杜甫《江畔独步寻花·其六》'),(756,'瀚海阑干百丈冰，愁云惨淡万里凝。','岑参《白雪歌送武判官归京》'),(757,'槛菊愁烟兰泣露。罗幕轻寒，燕子双飞去。','晏殊《蝶恋花·槛菊愁烟兰泣露》'),(758,'这次第，怎一个愁字了得！','李清照《声声慢·寻寻觅觅》'),(759,'纸灰飞作白蝴蝶，泪血染成红杜鹃。','高翥《清明日对酒》'),(760,'未收天子河湟地，不拟回头望故乡。','令狐楚《少年行四首·其三》'),(761,'山回路转不见君，雪上空留马行处。','岑参《白雪歌送武判官归京》'),(762,'天与短因缘，聚散常容易。','晏几道《生查子·狂花顷刻香》'),(763,'雁引愁心去，山衔好月来。','李白《与夏十二登岳阳楼》'),(764,'黄师塔前江水东，春光懒困倚微风。','杜甫《江畔独步寻花·其五》'),(765,'蜀江水碧蜀山青，圣主朝朝暮暮情。','白居易《长恨歌》'),(766,'一枝红艳露凝香，云雨巫山枉断肠。','李白《清平调·其二》'),(767,'白发渔樵江渚上，惯看秋月春风。','杨慎《临江仙·滚滚长江东逝水》'),(768,'河海不择细流，故能就其深；','李斯《谏逐客书》'),(769,'竹外一枝斜，想佳人，天寒日暮。','曹组《蓦山溪·梅》'),(770,'解落三秋叶，能开二月花。','李峤《风》'),(771,'荷叶罗裙一色裁，芙蓉向脸两边开。','王昌龄《采莲曲》'),(772,'欲穷千里目，更上一层楼。','王之涣《登鹳雀楼》'),(773,'摇落深知宋玉悲，风流儒雅亦吾师。','杜甫《咏怀古迹五首·其二》'),(774,'双星何事今宵会，遗我庭前月一钩。','德容《七夕二首·其一》'),(775,'常记溪亭日暮，沉醉不知归路。','李清照《如梦令·常记溪亭日暮》'),(776,'白锦无纹香烂漫，玉树琼葩堆雪。','丘处机《无俗念·灵虚宫梨花词》'),(777,'孤村落日残霞，轻烟老树寒鸦，一点飞鸿影下。','白朴《天净沙·秋》'),(778,'长安一片月，万户捣衣声。','李白《子夜吴歌·秋歌》'),(779,'横看成岭侧成峰，远近高低各不同。','苏轼《题西林壁》'),(780,'青春须早为，岂能长少年。','孟郊《劝学》'),(781,'想乌衣年少，芝兰秀发，戈戟云横。','叶梦得《八声甘州·寿阳楼八公山作》'),(782,'更无柳絮因风起，惟有葵花向日倾。','司马光《客中初夏》'),(783,'幸遇三杯酒好，况逢一朵花新。','朱敦儒《西江月·世事短如春梦》'),(784,'笛中闻折柳，春色未曾看。','李白《塞下曲六首·其一》'),(785,'春日宴，绿酒一杯歌一遍。','冯延巳《长命女·春日宴》'),(786,'多少天涯未归客，尽借篱落看秋风。','唐寅《菊花》'),(787,'青箬笠，绿蓑衣，斜风细雨不须归。','张志和《渔歌子·西塞山前白鹭飞》'),(788,'明月别枝惊鹊，清风半夜鸣蝉。','辛弃疾《西江月·夜行黄沙道中》'),(789,'此身合是诗人未？细雨骑驴入剑门。','陆游《剑门道中遇微雨》'),(790,'不知近水花先发，疑是经冬雪未销。','张谓《早梅》'),(791,'水急客舟疾，山花拂面香。','李白《秋浦歌十七首》'),(792,'红豆不堪看，满眼相思泪。','牛希济《生查子·新月曲如眉》'),(793,'别后不知君远近。触目凄凉多少闷。','欧阳修《玉楼春·别后不知君远近》'),(794,'最是仓皇辞庙日，教坊犹奏别离歌，垂泪对宫娥。','李煜《破阵子·四十年来家国》'),(795,'惨惨柴门风雪夜，此时有子不如无。','黄景仁《别老母》'),(796,'长记别伊时，和泪出门相送。','李存勖《如梦令·曾宴桃源深洞》'),(797,'佳节清明桃李笑，野田荒冢只生愁。','黄庭坚《清明》'),(798,'此花此叶常相映，翠减红衰愁杀人。','李商隐《赠荷花》'),(799,'扣舷独啸，不知今夕何夕。','张孝祥《念奴娇·过洞庭》'),(800,'火树银花合，星桥铁锁开。','苏味道《正月十五夜》'),(801,'忆昔午桥桥上饮，坐中多是豪英。','陈与义《临江仙·夜登小阁忆洛中旧游》'),(802,'绿酒初尝人易醉。一枕小窗浓睡。','晏殊《清平乐·金风细细》'),(803,'疾风知劲草，板荡识诚臣。','李世民《赐萧瑀》'),(804,'一年三百六十日，多是横戈马上行。','戚继光《马上作》'),(805,'十里青山远，潮平路带沙。数声啼鸟怨年华。','仲殊《南柯子·十里青山远》'),(806,'大鹏一日同风起，扶摇直上九万里。','李白《上李邕》'),(807,'为君持酒劝斜阳，且向花间留晚照。','宋祁《玉楼春·春景》'),(808,'三更月。中庭恰照梨花雪。','贺铸《子夜歌·三更月》'),(809,'古木阴中系短篷，杖藜扶我过桥东。','志南《绝句》'),(810,'乡村四月闲人少，才了蚕桑又插田。','翁卷《乡村四月》'),(811,'待何年归去，谈笑各争雄。','顾太清《高山流水·次夫子清风阁落成韵》'),(812,'片云天共远，永夜月同孤。','杜甫《江汉》'),(813,'惊回千里梦，已三更。起来独自绕阶行。','岳飞《小重山·昨夜寒蛩不住鸣》'),(814,'十年花骨东风泪，几点螺香素壁尘。','史达祖《鹧鸪天·搭柳栏干倚伫频》'),(815,'入则无法家拂士，出则无敌国外患者，国恒亡。','孟子及其弟子《生于忧患，死于安乐》'),(816,'自别后遥山隐隐，更那堪远水粼粼。','王实甫《十二月过尧民歌·别情》'),(817,'西北望乡何处是，东南见月几回圆。','白居易《八月十五日夜湓亭望月》'),(818,'车遥遥兮马洋洋，追思君兮不可忘。','傅玄《车遥遥篇》'),(819,'离愁渐远渐无穷，迢迢不断如春水。','欧阳修《踏莎行·候馆梅残》'),(820,'五月天山雪，无花只有寒。','李白《塞下曲六首·其一》'),(821,'积土成山，风雨兴焉；积水成渊，蛟龙生焉；','荀子《劝学》'),(822,'风暖鸟声碎，日高花影重。','杜荀鹤《春宫怨》'),(823,'春宵苦短日高起，从此君王不早朝。','白居易《长恨歌》'),(824,'章台柳，章台柳，昔日青青今在否？','韩翃《章台柳·寄柳氏》'),(825,'柳如眉，云似发，鲛绡雾縠笼香雪。','魏承班《渔歌子·柳如眉》'),(826,'最是人间留不住，朱颜辞镜花辞树。','王国维《蝶恋花·阅尽天涯离别苦》'),(827,'颠狂柳絮随风去，轻薄桃花逐水流。','杜甫《绝句漫兴九首·其五》'),(828,'白日不到处，青春恰自来。','袁枚《苔》'),(829,'当年万里觅封侯。匹马戍梁州。','陆游《诉衷情·当年万里觅封侯》'),(830,'故国三千里，深宫二十年。','张祜《宫词·故国三千里》'),(831,'问君何能尔？心远地自偏。','陶渊明《饮酒·其五》'),(832,'芳菲歇去何须恨，夏木阴阴正可人。','秦观《三月晦日偶题》'),(833,'云尽月如练，水凉风似秋。','欧阳詹《荆南夏夜水楼怀昭丘直上人云梦李莘》'),(834,'细雨湿衣看不见，闲花落地听无声。','刘长卿《别严士元》'),(835,'半亩方塘一鉴开，天光云影共徘徊。','朱熹《活水亭观书有感二首·其一》'),(836,'音尘绝，西风残照，汉家陵阙。','李白《忆秦娥·箫声咽》'),(837,'骊山语罢清宵半，泪雨霖铃终不怨。','纳兰性德《木兰词·拟古决绝词柬友》'),(838,'别君去兮何时还？且放白鹿青崖间。须行即骑访名山。','李白《梦游天姥吟留别 / 别东鲁诸公》'),(839,'君家何处住，妾住在横塘。','崔颢《长干行·君家何处住》'),(840,'淮南皓月冷千山，冥冥归去无人管。','姜夔《踏莎行·自沔东来》'),(841,'人归落雁后，思发在花前。','薛道衡《人日思归》'),(842,'猿啼客散暮江头，人自伤心水自流。','刘长卿《重送裴郎中贬吉州》'),(843,'英雄一去豪华尽，惟有青山似洛中。','许浑《金陵怀古》'),(844,'白头宫女在，闲坐说玄宗。','元稹《行宫》'),(845,'愁云淡淡雨潇潇。暮暮复朝朝。','石孝友《眼儿媚·愁云淡淡雨潇潇》'),(846,'年年负却花期！过春时，只合安排愁绪送春归。','张惠言《相见欢·年年负却花期》'),(847,'一片花飞减却春，风飘万点正愁人。','杜甫《曲江二首》'),(848,'孤雁不饮啄，飞鸣声念群。','杜甫《孤雁 / 后飞雁》'),(849,'独怜幽草涧边生，上有黄鹂深树鸣。','韦应物《滁州西涧》'),(850,'还似旧时游上苑，车如流水马如龙。','李煜《忆江南·多少恨》'),(851,'我见青山多妩媚，料青山见我应如是。','辛弃疾《贺新郎·甚矣吾衰矣》'),(852,'断送一生憔悴，只销几个黄昏。','赵令畤《清平乐·春风依旧》'),(853,'春风春雨花经眼，江北江南水拍天。','黄庭坚《次元明韵寄子由》'),(854,'万里无人收白骨，家家城下招魂葬。','张籍《征妇怨》'),(855,'唯有相思似春色，江南江北送君归。','王维《送沈子归江东 / 送沈子福之江东》'),(856,'过眼年华，动人幽意，相逢几番春换。','王沂孙《法曲献仙音·聚景亭梅次草窗韵》'),(857,'西窗下，风摇翠竹，疑是故人来。','秦观《满庭芳·碧水惊秋》'),(858,'不才明主弃，多病故人疏。','孟浩然《岁暮归南山 / 归故园作 / 归终南山》'),(859,'楼头残梦五更钟，花底离情三月雨。','晏殊《玉楼春·春恨》'),(860,'独在异乡为异客，每逢佳节倍思亲。','王维《九月九日忆山东兄弟 / 九月九忆山东兄弟》'),(861,'不知何岁月，得与尔同归？','韦承庆《南中咏雁诗》'),(862,'逢郎欲语低头笑，碧玉搔头落水中。','白居易《采莲曲》'),(863,'请君试问东流水，别意与之谁短长。','李白《金陵酒肆留别》'),(864,'古人今人若流水，共看明月皆如此。','李白《把酒问月·故人贾淳令予问之》'),(865,'绿树村边合，青山郭外斜。','孟浩然《过故人庄》'),(866,'未能抛得杭州去，一半勾留是此湖。','白居易《春题湖上》'),(867,'湘江两岸花木深，美人不见愁人心。','卢仝《有所思》'),(868,'谁怜一片影，相失万重云？','杜甫《孤雁 / 后飞雁》'),(869,'渭北春天树，江东日暮云。','杜甫《春日忆李白》'),(870,'莺初解语，最是一年春好处。','苏轼《减字木兰花·莺初解语》'),(871,'三五年时三五月，可怜杯酒不曾消。','黄景仁《绮怀》'),(872,'一叶渔船两小童，收篙停棹坐船中。','杨万里《舟过安仁》'),(873,'叶落当归根，云沉久必起。','钱嶫《悯黎咏》'),(874,'可怜九月初三夜，露似真珠月似弓。','白居易《暮江吟》'),(875,'参横斗转欲三更，苦雨终风也解晴。','苏轼《六月二十日夜渡海》'),(876,'淡淡梅花香欲染，丝丝柳带露初干。','曹雪芹《香菱咏月·其二》'),(877,'落叶聚还散，寒鸦栖复惊。','李白《三五七言 / 秋风词》'),(878,'竹影和诗瘦，梅花入梦香。','王庭筠《绝句·竹影和诗瘦》'),(879,'惟有绿荷红菡萏，卷舒开合任天真。','李商隐《赠荷花》'),(880,'可惜一溪风月，莫教踏碎琼瑶。','苏轼《西江月·顷在黄州》'),(881,'三军可夺帅也，匹夫不可夺志也。','佚名《论语十二章》'),(882,'归志宁无五亩园，读书本意在元元。','陆游《读书》'),(883,'朝真暮伪何人辨，古往今来底事无。','白居易《放言五首·其一》'),(884,'人生如寄，何事辛苦怨斜晖。','朱熹《水调歌头·隐括杜牧之齐山诗》'),(885,'子规夜半犹啼血，不信东风唤不回。','王令《送春》'),(886,'荷风送香气，竹露滴清响。','孟浩然《夏日南亭怀辛大》'),(887,'月明船笛参差起，风定池莲自在香。','秦观《纳凉》'),(888,'小扇引微凉，悠悠夏日长。','顾太清《菩萨蛮·端午日咏盆中菊》'),(889,'冉冉秋光留不住，满阶红叶暮。','李煜《谢新恩·冉冉秋光留不住》'),(890,'云散月明谁点缀？天容海色本澄清。','苏轼《六月二十日夜渡海》'),(891,'细雨斜风作晓寒。淡烟疏柳媚晴滩。','苏轼《浣溪沙·元丰七年十二月二十四日从泗州刘倩叔游南山》'),(892,'天苍苍，野茫茫。风吹草低见牛羊。','佚名《敕勒歌》'),(893,'终南阴岭秀，积雪浮云端。','祖咏《终南望余雪》'),(894,'砌下落梅如雪乱，拂了一身还满。','李煜《清平乐·别来春半》'),(895,'大雪压青松，青松挺且直。','陈毅《青松》'),(896,'砧杵敲残深巷月，井梧摇落故园秋。','陆游《秋思》'),(897,'江头未是风波恶，别有人间行路难！','辛弃疾《鹧鸪天·送人》'),(898,'半卷红旗临易水，霜重鼓寒声不起。','李贺《雁门太守行》'),(899,'杨柳青青江水平，闻郎江上踏歌声。','刘禹锡《竹枝词二首·其一》'),(900,'遥望洞庭山水色，白银盘里一青螺。','刘禹锡《望洞庭》'),(901,'欸乃一声山水绿。回看天际下中流，岩上无心云相逐。','柳宗元《渔翁》'),(902,'只在此山中，云深不知处。','贾岛《寻隐者不遇 / 孙革访羊尊师诗》'),(903,'亭亭山上松，瑟瑟谷中风。','刘桢《赠从弟》'),(904,'闺中少妇不知愁，春日凝妆上翠楼。','王昌龄《闺怨》'),(905,'小轩独坐相思处，情绪好无聊。','石孝友《眼儿媚·愁云淡淡雨潇潇》'),(906,'一寸丹心图报国，两行清泪为思亲。','于谦《立春日感怀》'),(907,'阳关万里道，不见一人归。','庾信《重别周尚书》'),(908,'自是浮生无可说。人间第一耽离别。','王国维《蝶恋花·满地霜华浓似雪》'),(909,'故人江海别，几度隔山川。','司空曙《云阳馆与韩绅宿别》'),(910,'秋风吹到江村，正黄昏，寂寞梧桐夜雨不开门。','顾彩《相见欢·秋风吹到江村》'),(911,'独出前门望野田，月明荞麦花如雪。','白居易《村夜》'),(912,'操吴戈兮被犀甲，车错毂兮短兵接。','屈原《国殇》'),(913,'狂风落尽深红色，绿叶成阴子满枝。','杜牧《怅诗》'),(914,'菡萏香销翠叶残，西风愁起绿波间。','李璟《摊破浣溪沙·菡萏香销翠叶残》'),(915,'故园东望路漫漫，双袖龙钟泪不干。','岑参《逢入京使》'),(916,'知我者，谓我心忧；不知我者，谓我何求。','佚名《黍离》'),(917,'梨花院落溶溶月，柳絮池塘淡淡风。','晏殊《无题·油壁香车不再逢》'),(918,'粉堕百花洲，香残燕子楼。','曹雪芹《唐多令·柳絮》'),(919,'书当快意读易尽，客有可人期不来。','陈师道《绝句·书当快意读易尽》'),(920,'叹十年心事，休休莫莫。','吴潜《满江红·豫章滕王阁》'),(921,'鱼书经岁绝，烛泪流残月。','徐灿《菩萨蛮·秋闺》'),(922,'人间有味是清欢。','苏轼《浣溪沙·细雨斜风作晓寒》'),(923,'老去悲秋强自宽，兴来今日尽君欢。','杜甫《九日蓝田崔氏庄》'),(924,'柔情似水，佳期如梦，忍顾鹊桥归路。','秦观《鹊桥仙·纤云弄巧》'),(925,'王孙莫把比蓬蒿，九日枝枝近鬓毛。','郑谷《菊》'),(926,'玉容寂寞泪阑干，梨花一枝春带雨。','白居易《长恨歌》'),(927,'今日斗酒会，明旦沟水头。','卓文君《白头吟》'),(928,'只恐双溪舴艋舟，载不动许多愁。','李清照《武陵春·春晚》'),(929,'不信比来长下泪，开箱验取石榴裙。','武则天《如意娘》'),(930,'无处不伤心，轻尘在玉琴。','纳兰性德《菩萨蛮·萧萧几叶风兼雨》'),(931,'风急桃花也似愁，点点飞红雨。','如晦《楚天遥过清江引·有意送春归》'),(932,'细雨梦回鸡塞远，小楼吹彻玉笙寒。','李璟《摊破浣溪沙·菡萏香销翠叶残》'),(933,'欲为圣明除弊事，肯将衰朽惜残年。','韩愈《左迁至蓝关示侄孙湘》'),(934,'胡未灭，鬓先秋。泪空流。','陆游《诉衷情·当年万里觅封侯》'),(935,'蜡烛有心还惜别，替人垂泪到天明。','杜牧《赠别》'),(936,'不似秋光，只与离人照断肠。','苏轼《减字木兰花·春月》'),(937,'卧龙跃马终黄土，人事音书漫寂寥。','杜甫《阁夜》'),(938,'春思乱，芳心碎。','惠洪《千秋岁·半身屏外》'),(939,'君不见管鲍贫时交，此道今人弃如土。','杜甫《贫交行》'),(940,'百啭千声随意移，山花红紫树高低。','欧阳修《画眉鸟》'),(941,'山际见来烟，竹中窥落日。','吴均《山中杂诗》'),(942,'唯有长江水，无语东流。','柳永《八声甘州·对潇潇暮雨洒江天》'),(943,'穿花蛱蝶深深见，点水蜻蜓款款飞。','杜甫《曲江二首》'),(944,'一水护田将绿绕，两山排闼送青来。','王安石《书湖阴先生壁》'),(945,'西北望长安，可怜无数山。','辛弃疾《菩萨蛮·书江西造口壁》'),(946,'飞流直下三千尺，疑是银河落九天。','李白《望庐山瀑布》'),(947,'青山横北郭，白水绕东城。','李白《送友人》'),(948,'种豆南山下，草盛豆苗稀。','陶渊明《归园田居·其三》'),(949,'泉眼无声惜细流，树阴照水爱晴柔。','杨万里《小池》'),(950,'烟霏霏。雪霏霏。雪向梅花枝上堆。','吴淑姬《长相思令·烟霏霏》'),(951,'玉碗冰寒滴露华，粉融香雪透轻纱。','晏殊《浣溪沙·玉碗冰寒滴露华》'),(952,'潮平两岸阔，风正一帆悬。','王湾《次北固山下》'),(953,'飞花两岸照船红，百里榆堤半日风。','陈与义《襄邑道中》'),(954,'西风吹老洞庭波，一夜湘君白发多。','唐温如《题龙阳县青草湖》'),(955,'风絮飘残已化萍，泥莲刚倩藕丝萦。','纳兰性德《山花子·风絮飘残已化萍》'),(956,'黄河之水天上来，奔流到海不复回。','李白《将进酒》'),(957,'寒蝉凄切，对长亭晚，骤雨初歇。','柳永《雨霖铃·寒蝉凄切》'),(958,'远书归梦两悠悠，只有空床敌素秋。','李商隐《端居》'),(959,'深秋帘幕千家雨，落日楼台一笛风。','杜牧《题宣州开元寺水阁阁下宛溪夹溪居人》'),(960,'人烟寒橘柚，秋色老梧桐。','李白《秋登宣城谢脁北楼》'),(961,'一霎荷塘过雨，明朝便是秋声。','项鸿祚《清平乐·池上纳凉》'),(962,'年年陌上生秋草，日日楼中到夕阳。','晏几道《鹧鸪天·醉拍春衫惜旧香》'),(963,'漠漠秋云起，稍稍夜寒生。','白居易《微雨夜行》'),(964,'水流花谢两无情，送尽东风过楚城。','崔涂《春夕》'),(965,'莫嫌举世无知己，未有庸人不忌才。','查慎行《三闾祠》'),(966,'童子解吟长恨曲，胡儿能唱琵琶篇。','李忱《吊白居易》'),(967,'何夜无月？何处无竹柏？但少闲人如吾两人者耳。','苏轼《记承天寺夜游 / 记承天夜游》'),(968,'依旧桃花面，频低柳叶眉。','韦庄《女冠子·昨夜夜半》'),(969,'戚姬髡发入舂市，万古共悲辛。','李白《中山孺子妾歌》'),(970,'山城过雨百花尽，榕叶满庭莺乱啼。','柳宗元《柳州二月榕叶落尽偶题》'),(971,'北风卷地白草折，胡天八月即飞雪。','岑参《白雪歌送武判官归京》'),(972,'小舟从此逝，江海寄余生。','苏轼《临江仙·夜饮东坡醒复醉》'),(973,'回首向来萧瑟处，归去，也无风雨也无晴。','苏轼《定风波·莫听穿林打叶声》'),(974,'北方有佳人，绝世而独立。','李延年《李延年歌》'),(975,'姑苏城外一茅屋，万树梅花月满天。','唐寅《把酒对月歌》'),(976,'山远翠眉长。高处凄凉。菊花清瘦杜秋娘。','吴文英《浪淘沙·九日从吴见山觅酒》'),(977,'苦恨年年压金线，为他人作嫁衣裳。','秦韬玉《贫女》'),(978,'昔别君未婚，儿女忽成行。','杜甫《赠卫八处士》'),(979,'松下问童子，言师采药去。','贾岛《寻隐者不遇 / 孙革访羊尊师诗》'),(980,'壮志饥餐胡虏肉，笑谈渴饮匈奴血。','岳飞《满江红·写怀》'),(981,'别有幽愁暗恨生，此时无声胜有声。','白居易《琵琶行 / 琵琶引》'),(982,'行人莫问当年事，故国东来渭水流。','许浑《咸阳城东楼 / 咸阳城西楼晚眺 / 西门》'),(983,'枕上十年事，江南二老忧，都到心头。','徐再思《水仙子·夜雨》'),(984,'载酒买花年少事，浑不似，旧心情。','卢祖皋《江城子·画楼帘暮卷新晴》'),(985,'夜雨剪春韭，新炊间黄粱。','杜甫《赠卫八处士》'),(986,'春风尔来为阿谁，蝴蝶忽然满芳草。','李白《山人劝酒》'),(987,'树阴满地日当午，梦觉流莺时一声。','苏舜钦《夏意》'),(988,'晴日暖风生麦气，绿阴幽草胜花时。','王安石《初夏即事》'),(989,'江上春山远，山下暮云长。','葛长庚《水调歌头·江上春山远》'),(990,'常恐秋风早，飘零君不知。','卢照邻《曲池荷》'),(991,'饮马渡秋水，水寒风似刀。','王昌龄《塞下曲四首》'),(992,'冰簟银床梦不成，碧天如水夜云轻。','温庭筠《瑶瑟怨》'),(993,'群芳过后西湖好，狼籍残红。','欧阳修《采桑子·群芳过后西湖好》'),(994,'人生有情泪沾臆，江水江花岂终极！','杜甫《哀江头》'),(995,'微微风簇浪，散作满河星。','查慎行《舟夜书所见》'),(996,'休说鲈鱼堪脍，尽西风，季鹰归未？','辛弃疾《水龙吟·登建康赏心亭》'),(997,'遥知独听灯前雨，转忆同看雪后山。','纳兰性德《于中好·送梁汾南还为题小影》'),(998,'人生如梦，一尊还酹江月。','苏轼《念奴娇·赤壁怀古》'),(999,'燕子飞时，绿水人家绕。','苏轼《蝶恋花·春景》'),(1000,'江晚正愁余，山深闻鹧鸪。','辛弃疾《菩萨蛮·书江西造口壁》'),(1001,'小山重叠金明灭，鬓云欲度香腮雪。','温庭筠《菩萨蛮·小山重叠金明灭》'),(1002,'漠漠轻寒上小楼。晓阴无赖似穷秋。淡烟流水画屏幽。','秦观《浣溪沙·漠漠轻寒上小楼》'),(1003,'妇人依倚子与夫，同居贫贱心亦舒。','张籍《征妇怨》'),(1004,'君安游兮西入秦，愿为影兮随君身。','傅玄《车遥遥篇》'),(1005,'燕山雪花大如席，片片吹落轩辕台。','李白《北风行》'),(1006,'不用思量今古，俯仰昔人非。','苏轼《八声甘州·寄参寥子》'),(1007,'不管烟波与风雨，载将离恨过江南。','郑文宝《柳枝词》'),(1008,'开轩面场圃，把酒话桑麻。','孟浩然《过故人庄》'),(1009,'国亡身殒今何有，只留离骚在世间。','张耒《和端午》'),(1010,'我歌月徘徊，我舞影零乱。','李白《月下独酌四首·其一》'),(1011,'谁知万里客，怀古正踌蹰。','陈子昂《岘山怀古》'),(1012,'草树知春不久归，百般红紫斗芳菲。','韩愈《晚春》'),(1013,'饮酒莫辞醉，醉多适不愁。','高适《淇上送韦司仓往滑台》'),(1014,'不知何日始工愁。记取那回花下一低头。','王国维《虞美人·弄梅骑竹嬉游日》'),(1015,'形影忽不见，翩翩伤我心。','曹植《杂诗六首·其一》'),(1016,'忍泪佯低面，含羞半敛眉。','韦庄《女冠子·四月十七》'),(1017,'落絮无声春堕泪，行云有影月含羞。','吴文英《浣溪沙·门隔花深梦旧游》'),(1018,'春如旧。人空瘦。泪痕红浥鲛绡透。','陆游《钗头凤·红酥手》'),(1019,'不惜千金买宝刀，貂裘换酒也堪豪。','秋瑾《对酒·不惜千金买宝刀》'),(1020,'半天凉月色，一笛酒人心。','袁枚《夜过借园见主人坐月下吹笛》'),(1021,'风雨梨花寒食过，几家坟上子孙来？','高启《送陈秀才还沙上省墓》'),(1022,'昼出耘田夜绩麻，村庄儿女各当家。','范成大《夏日田园杂兴·其七》'),(1023,'人间梦隔西风，算天上、年华一瞬。','吴文英《惜秋华·七夕》'),(1024,'人学始知道，不学非自然。','孟郊《劝学》'),(1025,'一蓑烟雨任平生。','苏轼《定风波·莫听穿林打叶声》'),(1026,'知否，知否？应是绿肥红瘦。','李清照《如梦令·昨夜雨疏风骤》'),(1027,'醉里挑灯看剑，梦回吹角连营。','辛弃疾《破阵子·为陈同甫赋壮词以寄之》'),(1028,'人似秋鸿来有信，事如春梦了无痕。','苏轼《正月二十日与潘郭二生出郊寻春忽记去年是日同至女王城作诗乃和前韵》'),(1029,'坑灰未冷山东乱，刘项原来不读书。','章碣《焚书坑》'),(1030,'登鸾车，侍轩辕，遨游青天中，其乐不可言。','李白《飞龙引二首·其一》'),(1031,'孰知不向边庭苦，纵死犹闻侠骨香。','王维《少年行四首》'),(1032,'伏波惟愿裹尸还，定远何须生入关。','李益《塞下曲》'),(1033,'南北山头多墓田，清明祭扫各纷然。','高翥《清明日对酒》'),(1034,'鸟飞反故乡兮，狐死必首丘。','屈原《九章》'),(1035,'人生有酒须当醉，一滴何曾到九泉。','高翥《清明日对酒》'),(1036,'无由持一碗，寄与爱茶人。','白居易《山泉煎茶有怀》'),(1037,'琴里知闻唯渌水，茶中故旧是蒙山。','白居易《琴茶》'),(1038,'欲黄昏。雨打梨花深闭门。','李重元《忆王孙·春词》'),(1039,'惊起却回头，有恨无人省。','苏轼《卜算子·黄州定慧院寓居作》'),(1040,'芭蕉不展丁香结，同向春风各自愁。','李商隐《代赠二首·其一》'),(1041,'相顾无言，惟有泪千行。','苏轼《江城子·乙卯正月二十日夜记梦》'),(1042,'剑外忽传收蓟北，初闻涕泪满衣裳。','杜甫《闻官军收河南河北》'),(1043,'遗民泪尽胡尘里，南望王师又一年。','陆游《秋夜将晓出篱门迎凉有感》'),(1044,'金陵津渡小山楼，一宿行人自可愁。','张祜《题金陵渡》'),(1045,'一场愁梦酒醒时，斜阳却照深深院。','晏殊《踏莎行·小径红稀》'),(1046,'一枝红杏出墙头，墙外行人正独愁。','吴融《途中见杏花》'),(1047,'寄语东阳沽酒市，拼一醉，而今乐事他年泪。','朱服《渔家傲·小雨纤纤风细细》'),(1048,'把酒送春春不语。黄昏却下潇潇雨。','朱淑真《蝶恋花·送春》'),(1049,'低花树映小妆楼，春入眉心两点愁。','白居易《春词》'),(1050,'我当二十不得意，一心愁谢如枯兰。','李贺《开愁歌》'),(1051,'浊酒不销忧国泪，救时应仗出群才。','秋瑾《黄海舟中日人索句并见日俄战争地图》'),(1052,'雨暗残灯棋散后，酒醒孤枕雁来初。','杜牧《齐安郡晚秋》'),(1053,'古路无行客，寒山独见君。','刘长卿《碧涧别墅喜皇甫侍御相访》'),(1054,'故人相望若为情。别愁深夜雨，孤影小窗灯。','陈克《临江仙·四海十年兵不解》'),(1055,'挥手自兹去，萧萧班马鸣。','李白《送友人》'),(1056,'当路谁相假，知音世所稀。','孟浩然《留别王侍御维 / 留别王维》'),(1057,'行尽江南，不与离人遇。','晏几道《蝶恋花·梦入江南烟水路》'),(1058,'可怜今夕月，向何处、去悠悠。','辛弃疾《木兰花慢·中秋饮酒将旦客谓前人诗词有赋待月无送月者因用天问体赋》'),(1059,'寂寂竟何待，朝朝空自归。','孟浩然《留别王侍御维 / 留别王维》'),(1060,'离别一何久，七度过中秋。','苏辙《水调歌头·徐州中秋》'),(1061,'不见又思量，见了还依旧。','李之仪《谢池春·残寒销尽》'),(1062,'写不成书，只寄得、相思一点。','张炎《解连环·孤雁》'),(1063,'同穴窅冥何所望，他生缘会更难期。','元稹《遣悲怀三首·其三》'),(1064,'残月出门时，美人和泪辞。','韦庄《菩萨蛮·红楼别夜堪惆怅》'),(1065,'妾身悔作商人妇，妾命当逢薄幸夫。','徐再思《阳春曲·闺怨》'),(1066,'一语不入意，从君万曲梁尘飞。','李白《夜坐吟》'),(1067,'若得山花插满头，莫问奴归处。','严蕊《卜算子·不是爱风尘》'),(1068,'白日登山望烽火，黄昏饮马傍交河。','李颀《古从军行》'),(1069,'楚天千里清秋，水随天去秋无际。','辛弃疾《水龙吟·登建康赏心亭》'),(1070,'峰峦如聚，波涛如怒，山河表里潼关路。','张养浩《山坡羊·潼关怀古》'),(1071,'昔闻洞庭水，今上岳阳楼。','杜甫《登岳阳楼》'),(1072,'三山半落青天外，二水中分白鹭洲。','李白《登金陵凤凰台》'),(1073,'若非群玉山头见，会向瑶台月下逢。','李白《清平调·其一》'),(1074,'料峭春风吹酒醒，微冷，山头斜照却相迎。','苏轼《定风波·三月七日》'),(1075,'山光悦鸟性，潭影空人心。','常建《题破山寺后禅院》'),(1076,'蓬山此去无多路，青鸟殷勤为探看。','李商隐《无题·相见时难别亦难》'),(1077,'巴山楚水凄凉地，二十三年弃置身。','刘禹锡《酬乐天扬州初逢席上见赠》'),(1078,'高楼送客不能醉，寂寂寒江明月心。','王昌龄《芙蓉楼送辛渐二首》'),(1079,'水晶帘外娟娟月，梨花枝上层层雪。','杨基《菩萨蛮·水晶帘外娟娟月》'),(1080,'风住尘香花已尽，日晚倦梳头。','李清照《武陵春·春晚》'),(1081,'春悄悄，夜迢迢。碧云天共楚宫遥。','晏几道《鹧鸪天·小令尊前见玉箫》'),(1082,'暖雨晴风初破冻，柳眼梅腮，已觉春心动。','李清照《蝶恋花·暖雨晴风初破冻》'),(1083,'怀君属秋夜，散步咏凉天。','韦应物《秋夜寄邱员外 / 秋夜寄丘二十二员外》'),(1084,'络纬秋啼金井阑，微霜凄凄簟色寒。','李白《长相思·其一》'),(1085,'丁丁漏水夜何长，漫漫轻云露月光。','张仲素《秋夜曲》'),(1086,'金井梧桐秋叶黄，珠帘不卷夜来霜。','王昌龄《长信怨》'),(1087,'红叶晚萧萧，长亭酒一瓢。','许浑《秋日赴阙题潼关驿楼 / 行次潼关逢魏扶东归》'),(1088,'午梦扁舟花底。香满两湖烟水。','杨万里《昭君怨·咏荷上雨》'),(1089,'未信此情难系绊，杨花犹有东风管。','苏轼《蝶恋花·蝶懒莺慵春过半》'),(1090,'律回岁晚冰霜少，春到人间草木知。','张栻《立春偶成》'),(1091,'深居俯夹城，春去夏犹清。','李商隐《晚晴》'),(1092,'彼此当年少，莫负好时光。','李隆基《好时光·宝髻偏宜宫样》'),(1093,'人恒过然后能改，困于心衡于虑而后作，征于色发于声而后喻。','孟子及其弟子《生于忧患，死于安乐》'),(1094,'季子正年少，匹马黑貂裘。','辛弃疾《水调歌头·舟次扬州和人韵》'),(1095,'借问酒家何处有？牧童遥指杏花村。','杜牧《清明》'),(1096,'啼时惊妾梦，不得到辽西。','金昌绪《春怨 / 伊州歌》'),(1097,'巧笑东邻女伴，采桑径里逢迎。','晏殊《破阵子·春景》'),(1098,'团扇，团扇，美人病来遮面。','王建《宫中调笑·团扇》'),(1099,'翠叶藏莺，朱帘隔燕。','晏殊《踏莎行·小径红稀》'),(1100,'丛菊两开他日泪，孤舟一系故园心。','杜甫《秋兴八首·其一》'),(1101,'桃未芳菲杏未红，冲寒先喜笑东风。','曹雪芹《咏红梅花得“红”字》'),(1102,'雪虐风饕愈凛然，花中气节最高坚。','陆游《落梅》'),(1103,'江天一色无纤尘，皎皎空中孤月轮。','张若虚《春江花月夜》'),(1104,'水国蒹葭夜有霜，月寒山色共苍苍。','薛涛《送友人》'),(1105,'忆对中秋丹桂丛。花在杯中。月在杯中。','辛弃疾《一剪梅·中秋元月》'),(1106,'明月如霜，好风如水，清景无限。','苏轼《永遇乐·彭城夜宿燕子楼》'),(1107,'酒困路长惟欲睡，日高人渴漫思茶。','苏轼《浣溪沙·簌簌衣巾落枣花》'),(1108,'人有悲欢离合，月有阴晴圆缺，此事古难全。','苏轼《水调歌头·丙辰中秋》'),(1109,'小时不识月，呼作白玉盘。','李白《古朗月行》'),(1110,'静夜沉沉，浮光霭霭，冷浸溶溶月。','丘处机《无俗念·灵虚宫梨花词》'),(1111,'白云千里万里，明月前溪后溪。','刘长卿《谪仙怨·晴川落日初低》'),(1112,'桃花一簇开无主，可爱深红爱浅红。','杜甫《江畔独步寻花·其五》'),(1113,'河畔青芜堤上柳，为问新愁，何事年年有？','冯延巳《鹊踏枝·谁道闲情抛弃久》'),(1114,'遍身罗绮者，不是养蚕人。','张俞《蚕妇》'),(1115,'素娥惟与月，青女不饶霜。','李商隐《十一月中旬至扶风界见梅花》'),(1116,'月明星稀，乌鹊南飞。绕树三匝，何枝可依？','曹操《短歌行》'),(1117,'大儿锄豆溪东，中儿正织鸡笼。','辛弃疾《清平乐·村居》'),(1118,'哀哀父母，生我劳瘁。','佚名《蓼莪》'),(1119,'人生百年有几，念良辰美景，休放虚过。','元好问《骤雨打新荷》'),(1120,'庭轩寂寞近清明，残花中酒，又是去年病。','张先《青门引·春思》'),(1121,'可堪孤馆闭春寒，杜鹃声里斜阳暮。','秦观《踏莎行·郴州旅舍》'),(1122,'笙歌散尽游人去，始觉春空。','欧阳修《采桑子·群芳过后西湖好》'),(1123,'最爱湖东行不足，绿杨阴里白沙堤。','白居易《钱塘湖春行》'),(1124,'长安白日照春空，绿杨结烟垂袅风。','李白《阳春歌》'),(1125,'风蒲猎猎小池塘。过雨荷花满院香。','李重元《忆王孙·夏词》'),(1126,'别院深深夏席清，石榴开遍透帘明。','苏舜钦《夏意》'),(1127,'湖光秋月两相和，潭面无风镜未磨。','刘禹锡《望洞庭》'),(1128,'长风万里送秋雁，对此可以酣高楼。','李白《宣州谢脁楼饯别校书叔云 / 陪侍御叔华登楼歌》'),(1129,'荒城临古渡，落日满秋山。','王维《归嵩山作》'),(1130,'满园花菊郁金黄，中有孤丛色似霜。','白居易《重阳席上赋白菊》'),(1131,'云无心以出岫，鸟倦飞而知还。','陶渊明《归去来兮辞·并序》'),(1132,'浮云蔽白日，游子不顾返。','佚名《行行重行行》'),(1133,'泠泠七弦上，静听松风寒。','刘长卿《听弹琴》'),(1134,'锦江春色来天地，玉垒浮云变古今。','杜甫《登楼》'),(1135,'岱宗夫如何？齐鲁青未了。','杜甫《望岳》'),(1136,'梅雪争春未肯降，骚人搁笔费评章。','卢梅坡《雪梅·其一》'),(1137,'天将暮，雪乱舞，半梅花半飘柳絮。','马致远《寿阳曲·江天暮雪》'),(1138,'草枯鹰眼疾，雪尽马蹄轻。','王维《观猎》'),(1139,'中岁颇好道，晚家南山陲。','王维《终南别业 / 初至山中 / 入山寄城中故人》'),(1140,'平芜尽处是春山，行人更在春山外。','欧阳修《踏莎行·候馆梅残》'),(1141,'寒山转苍翠，秋水日潺湲。','王维《辋川闲居赠裴秀才迪》'),(1142,'淮水东边旧时月，夜深还过女墙来。','刘禹锡《金陵五题·石头城》'),(1143,'最是繁丝摇落后，转教人忆春山。','纳兰性德《临江仙·寒柳》'),(1144,'浮天水送无穷树，带雨云埋一半山。','辛弃疾《鹧鸪天·送人》'),(1145,'山寺月中寻桂子，郡亭枕上看潮头。','白居易《忆江南·江南忆》'),(1146,'重见金英人未见。相思一夜天涯远。','晏几道《蝶恋花·黄菊开时伤聚散》'),(1147,'闲坐悲君亦自悲，百年多是几多时。','元稹《遣悲怀三首·其三》'),(1148,'雁字无多，写得相思几许。','周密《扫花游·九日怀归》'),(1149,'明岁秋风知再会，暂时分手莫相思。','曹雪芹《残菊》'),(1150,'故乡今夜思千里，霜鬓明朝又一年。','高适《除夜作》'),(1151,'搴帷拜母河梁去，白发愁看泪眼枯。','黄景仁《别老母》'),(1152,'谁知江上酒，还与故人倾。','周紫芝《临江仙·送光州曾使君》'),(1153,'丈夫贫贱应未足，今日相逢无酒钱。','高适《别董大二首》'),(1154,'鸿雁在云鱼在水。惆怅此情难寄。','晏殊《清平乐·红笺小字》'),(1155,'杀人亦有限，列国自有疆。','杜甫《前出塞九首·其六》'),(1156,'吴宫花草埋幽径，晋代衣冠成古丘。','李白《登金陵凤凰台》'),(1157,'赏心乐事共谁论？花下销魂，月下销魂。','唐寅《一剪梅·雨打梨花深闭门》'),(1158,'含情欲说宫中事，鹦鹉前头不敢言。','朱庆馀《宫词 / 宫中词》'),(1159,'自春来、惨绿愁红，芳心是事可可。','柳永《定风波·自春来》'),(1160,'一上高城万里愁，蒹葭杨柳似汀洲。','许浑《咸阳城东楼 / 咸阳城西楼晚眺 / 西门》'),(1161,'纱窗日落渐黄昏，金屋无人见泪痕。','刘方平《春怨》'),(1162,'正是江南好风景，落花时节又逢君。','杜甫《江南逢李龟年》'),(1163,'千淘万漉虽辛苦，吹尽狂沙始到金。','刘禹锡《浪淘沙九首》'),(1164,'金樽清酒斗十千，玉盘珍羞直万钱。','李白《行路难·其一》'),(1165,'狎兴生疏，酒徒萧索，不似少年时。','柳永《少年游·长安古道马迟迟》'),(1166,'一杯酒，问何似，身后名？','辛弃疾《水调歌头·壬子三山被召陈端仁给事饮饯席上作》'),(1167,'万里中原烽火北，一尊浊酒戍楼东。','张孝祥《浣溪沙·霜日明霄水蘸空》'),(1168,'嗟余听鼓应官去，走马兰台类转蓬。','李商隐《无题·昨夜星辰昨夜风》'),(1169,'雁声远过潇湘去，十二楼中月自明。','温庭筠《瑶瑟怨》'),(1170,'烟柳画桥，风帘翠幕，参差十万人家。','柳永《望海潮·东南形胜》'),(1171,'汉兵已略地，四方楚歌声。','虞姬《和项王歌》'),(1172,'陌上深深，依旧年时辙。','王国维《蝶恋花·满地霜华浓似雪》'),(1173,'有约不来过夜半，闲敲棋子落灯花。','赵师秀《约客》'),(1174,'流光容易把人抛，红了樱桃，绿了芭蕉。','蒋捷《一剪梅·舟过吴江》'),(1175,'天涯何处无芳草！墙里秋千墙外道。','苏轼《蝶恋花·春景》'),(1176,'粗缯大布裹生涯，腹有诗书气自华。','苏轼《和董传留别》'),(1177,'来岁花前。又是今年忆去年。','吕本中《减字木兰花·去年今夜》'),(1178,'流年莫虚掷，华发不相容。','方干《送从兄郜 / 韦郜 / 途中别孙璐》'),(1179,'当年得意如芳草。日日春风好。','辛弃疾《虞美人·赋虞美人草》'),(1180,'弱冠弄柔翰，卓荦观群书。','左思《咏史八首·其一》'),(1181,'男儿西北有神州，莫滴水西桥畔泪。','刘克庄《玉楼春·戏林推》'),(1182,'马作的卢飞快，弓如霹雳弦惊。','辛弃疾《破阵子·为陈同甫赋壮词以寄之》'),(1183,'艰难苦恨繁霜鬓，潦倒新停浊酒杯。','杜甫《登高》'),(1184,'高情已逐晓云空。不与梨花同梦。','苏轼《西江月·梅花》'),(1185,'竹杖芒鞋轻胜马，谁怕？','苏轼《定风波·莫听穿林打叶声》'),(1186,'门外无人问落花，绿阴冉冉遍天涯。','曹豳《春暮·门外无人问落花》'),(1187,'而今识尽愁滋味，欲说还休。','辛弃疾《丑奴儿·书博山道中壁》'),(1188,'一声何满子，双泪落君前。','张祜《宫词·故国三千里》'),(1189,'日长篱落无人过，惟有蜻蜓蛱蝶飞。','范成大《四时田园杂兴·其二》'),(1190,'晓镜但愁云鬓改，夜吟应觉月光寒。','李商隐《无题·相见时难别亦难》'),(1191,'胡雁哀鸣夜夜飞，胡儿眼泪双双落。','李颀《古从军行》'),(1192,'昨风一吹无人会，今夜清光似往年。','白居易《八月十五日夜湓亭望月》'),(1193,'人老去西风白发，蝶愁来明日黄花。','张可久《折桂令·九日》'),(1194,'翠蛾轻敛意沉吟，沾襟，无人知此心。','孙光宪《河传·花落》'),(1195,'影孤怜夜永。永夜怜孤影。','苏轼《菩萨蛮·回文秋闺怨》'),(1196,'人去空流水，花飞半掩门。','秦观《南歌子·香墨弯弯画》'),(1197,'君看六幅南朝事，老木寒云满故城。','韦庄《金陵图》'),(1198,'恰似春风相欺得，夜来吹折数枝花。','杜甫《绝句漫兴九首·其二》'),(1199,'春色恼人眠不得，月移花影上栏杆。','王安石《春夜》'),(1200,'春路雨添花，花动一山春色。','秦观《好事近·梦中作》'),(1201,'寄语洛城风日道，明年春色倍还人。','杜审言《春日京中有怀》'),(1202,'花开不并百花丛，独立疏篱趣未穷。','郑思肖《画菊》'),(1203,'不知来岁牡丹时，再相逢何处。','叶清臣《贺圣朝·留别》'),(1204,'君到姑苏见，人家尽枕河。','杜荀鹤《送人游吴》'),(1205,'午醉醒来愁未醒。送春春去几时回。','张先《天仙子·水调数声持酒听》'),(1206,'明日相思莫上楼，楼上多风雨。','游次公《卜算子·风雨送人来》'),(1207,'望阙云遮眼，思乡雨滴心。','白居易《阴雨》'),(1208,'城上高楼接大荒，海天愁思正茫茫。','柳宗元《登柳州城楼寄漳汀封连四州》'),(1209,'四面边声连角起，千嶂里，长烟落日孤城闭。','范仲淹《渔家傲·秋思》'),(1210,'后夜相思，尘随马去，月逐舟行。','刘过《柳梢青·送卢梅坡》'),(1211,'晨起动征铎，客行悲故乡。','温庭筠《商山早行》'),(1212,'寄相思，寒雨灯窗，芙蓉旧院。','吴文英《宴清都·秋感》'),(1213,'天长路远魂飞苦，梦魂不到关山难。','李白《长相思·其一》'),(1214,'旋开旋落旋成空，白发多情人更惜。','司空图《酒泉子·买得杏花》'),(1215,'夜长争得薄情知，春初早被相思染。','姜夔《踏莎行·自沔东来》'),(1216,'三春白雪归青冢，万里黄河绕黑山。','柳中庸《征人怨 / 征怨》'),(1217,'莫遣只轮归海窟，仍留一箭射天山。','李益《塞下曲》'),(1218,'云收雨过波添，楼高水冷瓜甜，绿树阴垂画檐。','白朴《天净沙·夏》'),(1219,'京口瓜洲一水间，钟山只隔数重山。','王安石《泊船瓜洲》'),(1220,'万里赴戎机，关山度若飞。','佚名《木兰诗 / 木兰辞》'),(1221,'溪深难受雪，山冻不流云。','洪升《雪望》'),(1222,'长江悲已滞，万里念将归。','王勃《山中》'),(1223,'杨柳东风树，青青夹御河。','王之涣《送别》'),(1224,'溪深古雪在，石断寒泉流。','李白《寻高凤石门山中元丹丘》'),(1225,'伫倚危楼风细细。望极春愁，黯黯生天际。','柳永《蝶恋花·伫倚危楼风细细》'),(1226,'大风起兮云飞扬。威加海内兮归故乡。安得猛士兮守四方！','刘邦《大风歌》'),(1227,'风急天高猿啸哀，渚清沙白鸟飞回。','杜甫《登高》'),(1228,'晚风庭院落梅初。淡云来往月疏疏。','李清照《浣溪沙·髻子伤春慵更梳》'),(1229,'山黛远，月波长，暮云秋影蘸潇湘。','蔡松年《鹧鸪天·赏荷》'),(1230,'梅定妒，菊应羞。画阑开处冠中秋。','李清照《鹧鸪天·桂花》'),(1231,'黄菊枝头生晓寒。人生莫放酒杯干。','黄庭坚《鹧鸪天·坐中有眉山隐客史应之和前韵》'),(1232,'楼倚霜树外，镜天无一毫。','杜牧《长安秋望》'),(1233,'西风乱叶溪桥树。秋在黄花羞涩处。','张榘《青玉案·被檄出郊题陈氏山居》'),(1234,'秋草独寻人去后，寒林空见日斜时。','刘长卿《长沙过贾谊宅》'),(1235,'荷花开后西湖好，载酒来时。','欧阳修《采桑子·荷花开后西湖好》'),(1236,'夜合花开香满庭，夜深微雨醉初醒。','窦叔向《夏夜宿表兄话旧》'),(1237,'报道先生归也，杏花春雨江南。','虞集《风入松·寄柯敬仲》'),(1238,'春风不解禁杨花，濛濛乱扑行人面。','晏殊《踏莎行·小径红稀》'),(1239,'夜雨连明春水生，娇云浓暖弄阴晴。','苏舜钦《初晴游沧浪亭》'),(1240,'夜来南风起，小麦覆陇黄。','白居易《观刈麦》'),(1241,'亦知合被才名折，二十三年折太多。','白居易《醉赠刘二十八使君》'),(1242,'镜中已觉星星误。人不负春春自负。','辛弃疾《玉楼春·风前欲劝春光住》'),(1243,'爱子心无尽，归家喜及辰。','蒋士铨《岁暮到家》'),(1244,'读书不作儒生酸，跃马西入金城关。','谢逸《送董元达》'),(1245,'昨日邻家乞新火，晓窗分与读书灯。','王禹偁《清明》'),(1246,'休言女子非英物，夜夜龙泉壁上鸣。','秋瑾《鹧鸪天·祖国沉沦感不禁》'),(1247,'妾家高楼连苑起，良人执戟明光里。','张籍《节妇吟·寄东平李司空师道》'),(1248,'孤灯不明思欲绝，卷帷望月空长叹。美人如花隔云端！','李白《长相思·其一》'),(1249,'卢家少妇郁金堂，海燕双栖玳瑁梁。','沈佺期《古意呈补阙乔知之 / 古意 / 独不见》'),(1250,'劳歌一曲解行舟，红叶青山水急流。','许浑《谢亭送别》'),(1251,'千里稻花应秀色，五更桐叶最佳音。','曾几《苏秀道中》'),(1252,'世间花叶不相伦，花入金盆叶作尘。','李商隐《赠荷花》'),(1253,'风波不信菱枝弱，月露谁教桂叶香。','李商隐《无题·重帏深下莫愁堂》'),(1254,'水风轻，蘋花渐老，月露冷、梧叶飘黄。','柳永《玉蝴蝶·望处雨收云断》'),(1255,'清江一曲柳千条，二十年前旧板桥。','刘禹锡《杨柳枝 / 柳枝词》'),(1256,'陌上风光浓处。第一寒梅先吐。','李弥逊《十样花·陌上风光浓处》'),(1257,'百亩庭中半是苔，桃花净尽菜花开。','刘禹锡《再游玄都观》'),(1258,'开花必早落，桃李不如松。','李白《箜篌谣》'),(1259,'笙歌散后酒初醒，深院月斜人静。','司马光《西江月·宝髻松松挽就》'),(1260,'家家乞巧望秋月，穿尽红丝几万条。','林杰《乞巧》'),(1261,'边月随弓影，胡霜拂剑花。','李白《塞下曲六首》'),(1262,'千门万户曈曈日，总把新桃换旧符。','王安石《元日》'),(1263,'满眼游丝兼落絮，红杏开时，一霎清明雨。','冯延巳《鹊踏枝·清明》'),(1264,'我本楚狂人，凤歌笑孔丘。','李白《庐山谣寄卢侍御虚舟》'),(1265,'人生不相见，动如参与商。','杜甫《赠卫八处士》'),(1266,'唯有牡丹真国色，花开时节动京城。','刘禹锡《赏牡丹》'),(1267,'冲天香阵透长安，满城尽带黄金甲。','黄巢《不第后赋菊》'),(1268,'柳外轻雷池上雨，雨声滴碎荷声。小楼西角断虹明。','欧阳修《临江仙·柳外轻雷池上雨》'),(1269,'桃花流水窅然去，别有天地非人间。','李白《山中问答》'),(1270,'烟水茫茫，千里斜阳暮。山无数。乱红如雨。','秦观《点绛唇·桃源》'),(1271,'玉楼金阙慵归去，且插梅花醉洛阳。','朱敦儒《鹧鸪天·西都作》'),(1272,'青青河畔草，郁郁园中柳。','佚名《青青河畔草》'),(1273,'掩柴扉，谢他梅竹伴我冷书斋。','沈自晋《玉芙蓉·雨窗小咏》'),(1274,'水晶帘不下，云母屏开，冷浸佳人淡脂粉。','晁补之《洞仙歌·泗州中秋作》'),(1275,'辛苦遭逢起一经，干戈寥落四周星。','文天祥《过零丁洋》'),(1276,'路人借问遥招手，怕得鱼惊不应人。','胡令能《小儿垂钓》'),(1277,'儿童相见不相识，笑问客从何处来。','贺知章《回乡偶书二首·其一》'),(1278,'日出入安穷？时世不与人同。','佚名《日出入》'),(1279,'年年今夜，月华如练，长是人千里。','范仲淹《御街行·秋日怀旧》'),(1280,'若待明朝风雨过，人在天涯！春在天涯。','虞集《南乡一剪梅·招熊少府》'),(1281,'新年都未有芳华，二月初惊见草芽。','韩愈《春雪》'),(1282,'春雪满空来，触处似花开。','赵嘏《喜张沨及第》'),(1283,'长于春梦几多时，散似秋云无觅处。','晏殊《木兰花·燕鸿过后莺归去》'),(1284,'叹息老来交旧尽，睡来谁共午瓯茶。','陆游《幽居初夏》'),(1285,'戍鼓断人行，边秋一雁声。','杜甫《月夜忆舍弟》'),(1286,'秋晚莼鲈江上，夜深儿女灯前。','辛弃疾《木兰花慢·滁州送范倅》'),(1287,'寸寸微云，丝丝残照，有无明灭难消。','贺双卿《凤凰台上忆吹箫·寸寸微云》'),